insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('demokratische-uadnung', 'Demokratische Uadnung', '', '', '', '', 'Demokratische Ordnung', '[{"kategorie": "pol.", "text": "\"das politische System und die staatlichen Strukturen in Österreich, die auf den Prinzipien der Demokratie beruhen\""}, {"kategorie": "", "text": "Diese Ordnung garantiert, dass alle [[Staatsgewalt]] vom Volk ausgeht und das Volk über gewählte Vertreter oder direkt an politischen Entscheidungen teilnimmt"}, {"kategorie": "", "text": "Sie ist in der österreichischen [[Bundesverfassung]] verankert und basiert auf mehreren grundlegenden Prinzipien"}, {"kategorie": "", "text": "Österreich ist eine [[repräsentative]] Demokratie, in der das Volk seine politischen Vertreter in regelmäßigen, freien Wahlen bestimmt. Diese gewählten Organe ([[Nationalrat]], [[Bundesrat]], [[Landtage]] und [[Gemeinderäte]]) haben die Aufgabe, Gesetze zu erlassen und die Regierung zu kontrollieren"}, {"kategorie": "", "text": "Die demokratische Ordnung in Österreich ist durch eine klare Trennung der drei Gewalten – [[Legislative]] (gesetzgebende Gewalt), [[Exekutive]] (ausführende Gewalt) und [[Judikative]] (rechtsprechende Gewalt) – gekennzeichnet. Diese Trennung verhindert Machtmissbrauch und sichert die Unabhängigkeit der [[Rechtsprechung]]"}, {"kategorie": "", "text": "Die demokratische Ordnung verpflichtet alle staatlichen Organe zur Einhaltung der Gesetze ([[Legalitätsprinzip]]), die ihrerseits auf demokratisch legitimierten Entscheidungen beruhen. Dadurch wird die [[Rechtsstaatlichkeit]] gewährleistet, die allen Bürgern gleiche Rechte und Pflichten zusichert"}, {"kategorie": "", "text": "Neben der repräsentativen Demokratie gibt es in Österreich auch Instrumente direkter Demokratie, wie [[Volksabstimmungen]], [[Volksbegehren]] und Volksbefragungen, die es der Bevölkerung ermöglichen, an wichtigen politischen Entscheidungen unmittelbar teilzunehmen"}, {"kategorie": "", "text": "Die demokratische Ordnung schützt die [[Grund-]] und Freiheitsrechte aller Bürgerinnen und Bürger. Dazu zählen Meinungsfreiheit, Versammlungsfreiheit, Pressefreiheit und das Recht auf Gleichheit vor dem Gesetz. Diese Rechte sind in der Verfassung und internationalen Menschenrechtsabkommen verankert."}]'::jsonb, ''),
  ('oestarreichische-vawoitung', 'Östarreichische Vawoitung', '', '', '', '', 'Österreichische Verwaltung', '[{"kategorie": "", "text": "Sie ist Teil der [[Exekutive]] und umfasst Aufgabenbereiche auf Bundes-, Landes- und Gemeindeebene: (i) Bundesverwaltung: Die Aufgaben werden im Namen des Bundes ausgeführt und umfassen Bereiche wie innere Sicherheit, Bildung, und Finanzen. Die Bundesverwaltung wird durch [[Ministerien]] und [[Bundesbehörden]] organisiert;  (ii) Landesverwaltung: Die Länder sind für die Vollziehung bestimmter eigener Angelegenheiten verantwortlich, etwa im Bereich des Schulwesens und der Raumplanung. Die Verwaltung erfolgt durch die [[Landesregierungen]] und -behörden;  (iii) Gemeindeebene: Die Gemeinden übernehmen lokale Verwaltungsaufgaben wie Meldewesen, Bauangelegenheiten und die örtliche Sicherheit"}, {"kategorie": "", "text": "Die Verwaltung arbeitet im Rahmen der Gesetze und wird durch die politischen Organe und [[Gerichte]] kontrolliert"}, {"kategorie": "", "text": "Die österreichische Verwaltung ist zudem vom Prinzip des [[Legalitätsprinzips]] geprägt, wonach alle Verwaltungsakte an die bestehenden Gesetze gebunden sind. Dieses Prinzip sichert eine gesetzeskonforme, transparente und rechtsstaatliche Verwaltung in Österreich."}]'::jsonb, ''),
  ('hauns-kelsn', 'Hauns Kelsn', '', '', '', '', 'Hans Kelsen', '[{"kategorie": "hist.", "text": "\"österreichischer Rechtswissenschaftler (1881–1973), der als Architekt der österreichischen [[Bundesverfassung]] von 1920 gilt\""}, {"kategorie": "", "text": "Diese Verfassung führte die Verfassungsgerichtsbarkeit ein, ein damals revolutionäres Konzept, das Kelsen entwickelte und das Österreich ermöglichte, Gesetze auf ihre Verfassungsmäßigkeit hin zu überprüfen. Dieses Modell wurde weltweit wegweisend und ist bis heute ein zentraler Bestandteil der österreichischen [[Rechtsordnung]]"}, {"kategorie": "", "text": "Kelsen ist zudem der Begründer der Reinen Rechtslehre, die das Recht als ein eigenständiges, normatives System betrachtet, losgelöst von politischen und moralischen Einflüssen"}, {"kategorie": "", "text": "Aufgrund seines jüdischen Hintergrundes musste Kelsen in den 1930er-Jahren Europa verlassen und emigrierte schließlich in die USA, wo er an mehreren Universitäten, darunter die University of California, Berkeley, lehrte"}, {"kategorie": "", "text": "Kelsens Werk und seine Theorien haben das österreichische Rechtssystem tief geprägt und bilden die Basis für das moderne Verständnis von Recht und Staat in Österreich."}]'::jsonb, ''),
  ('sozialdemokratische-oabeitapartei', 'Sozialdemokratische Oabeitapartei', '', '', '', '', 'Sozialdemokratische Arbeiterpartei', '[{"kategorie": "", "text": "Die SDAP setzte sich für die Interessen der Arbeiterklasse ein und verfolgte das Ziel einer sozialistischen Gesellschaftsordnung. Sie ist die Vorgängerin der heutigen [[Sozialdemokratischen]] Partei Österreichs ([[SPÖ]])"}, {"kategorie": "", "text": "Die SDAP war eine marxistisch orientierte Partei, die sich jedoch an demokratischen Grundsätzen orientierte. Sie strebte eine sozialistische Gesellschaftsordnung an, in der die Arbeiterklasse eine zentrale Rolle spielt, lehnte aber den gewaltsamen Umsturz ab und setzte stattdessen auf demokratische Reformen"}, {"kategorie": "", "text": "Die Partei vertrat die Interessen der Arbeiter und forderte umfassende soziale Reformen, darunter den Acht-Stunden-Tag, bessere Arbeitsbedingungen, soziale Absicherung und gleiche Rechte für alle Bürger. Ihr Programm zielte auf eine gerechtere Verteilung von Reichtum und Ressourcen ab"}, {"kategorie": "", "text": "Die SDAP legte großen Wert auf Bildung und politische Aufklärung der Arbeiterklasse. Sie baute ein breites Netz an Bildungseinrichtungen, Büchereien, Vereinen und Kulturinstitutionen auf, um die politische Bildung und das Gemeinschaftsleben der Arbeiter zu fördern. Dieses Konzept nannte sich [[Austromarxismus]] und zielte auf eine schrittweise Reform der Gesellschaft in Richtung Sozialismus"}, {"kategorie": "", "text": "In der Ersten Republik prägte die SDAP vor allem Wien, wo sie mit ihrer Mehrheit im [[Gemeinderat]] ein einzigartiges Sozialprogramm verwirklichte. Der Bau von großzügigen [[Gemeindebauten]] (sozialen Wohnanlagen) und die Schaffung öffentlicher Einrichtungen für Gesundheit, Bildung und Freizeitgestaltung im sogenannten [[Roten]] Wien machten die Stadt zu einem Modell der sozialdemokratischen Stadtpolitik"}, {"kategorie": "", "text": "Die SDAP stand in scharfer Opposition zur [[Christlich-Sozialen]] Partei (CSP), mit der sie um die politische Vorherrschaft in Österreich kämpfte. Die zunehmenden Spannungen führten schließlich zum [[Österreichischen]] Bürgerkrieg ([[Februaraufstand]] 1934), in dem paramilitärische Verbände der Sozialdemokraten ([[Schutzbund]]) gegen die [[Heimwehr]] (unterstützt von der CSP und dem autoritären [[Ständestaat]]) kämpften. Nach der Niederlage des Schutzbundes wurde die SDAP verboten, und viele ihrer Mitglieder wurden verfolgt oder inhaftiert"}, {"kategorie": "", "text": "Nach dem [[Zweiten]] Weltkrieg wurde die SDAP unter dem neuen Namen Sozialistische Partei Österreichs ([[SPÖ]]) wiedergegründet (heute [[Sozialdemokratische]] Partei Österreichs). Die SPÖ knüpfte an viele ihrer sozialen und demokratischen Ziele an und ist bis heute eine der bedeutendsten politischen Kräfte in Österreich."}]'::jsonb, ''),
  ('christlich-soziale-partei', 'Christlich-Soziale Partei', '', '', '', '', 'Christlich-Soziale Partei', '[{"kategorie": "", "text": "Sie war während der späten [[Habsburgermonarchie]] und der [[Ersten]] Republik Österreich eine der einflussreichsten Parteien und setzte sich für die Interessen des katholischen Bürgertums sowie der bäuerlichen und kleinbürgerlichen Bevölkerung ein. Die CSP gilt als eine der Vorläuferparteien der heutigen [[Österreichischen]] Volkspartei ([[ÖVP]])"}, {"kategorie": "", "text": "Die CSP war eng mit der katholischen Kirche verbunden und vertrat konservative Werte, die auf den Lehren der katholischen Soziallehre basierten. Die Partei betonte Familie, Religion und soziale Gerechtigkeit als zentrale Werte und lehnte den Liberalismus und Sozialismus entschieden ab"}, {"kategorie": "", "text": "Die Partei engagierte sich für soziale Reformen und Maßnahmen zum Schutz von Bauern und Kleinbürgern. Allerdings vertrat sie auch antisemitische Positionen, die insbesondere von ihrem Gründer, [[Karl]] Lueger, gefördert wurden. [[Dr]]. Karl Lueger, der auch [[Bürgermeister]] von Wien war, nutzte antisemitische Ressentiments für den politischen Aufstieg der Partei"}, {"kategorie": "", "text": "Nach dem [[Ersten]] Weltkrieg und dem Zusammenbruch der [[Habsburgermonarchie]] war die CSP eine der beiden dominierenden Parteien in der [[Ersten]] Republik. Sie stellte mehrere Bundeskanzler und war gemeinsam mit der [[Sozialdemokratischen]] Arbeiterpartei (SDAP) maßgeblich an der politischen Gestaltung beteiligt"}, {"kategorie": "", "text": "Mit der Errichtung des autoritären [[Ständestaats]] 1934, der von konservativen und klerikalen Kräften gestützt wurde, ging die CSP in der Einheitspartei [[Vaterländische]] Front auf und löste sich als eigenständige Partei auf"}, {"kategorie": "", "text": "Nach dem [[Zweiten]] Weltkrieg knüpfte die neu gegründete [[Österreichische]] Volkspartei ([[ÖVP]]) an das Erbe der CSP an und übernahm deren katholisch-konservative Tradition"}, {"kategorie": "", "text": "Die Christlich-Soziale Partei prägte die österreichische Politik und die Gesellschaft tiefgehend und legte durch ihre konservativen und sozialen Grundsätze den Grundstein für die österreichische Volksbewegung der Nachkriegszeit."}]'::jsonb, ''),
  ('grossdeitsche-voikspartei', 'Großdeitsche Voikspartei', '', '', '', '', 'Großdeutsche Volkspartei', '[{"kategorie": "", "text": "Die GDVP sah Österreich als Teil einer größeren deutschen Nation und strebte einen [[Anschluss]] Österreichs an das [[Deutsche]] Reich an. Diese Forderung fand nach dem Ende des [[Ersten]] Weltkriegs und dem Zerfall der [[Österreich-Ungarischen]] Monarchie in bestimmten Kreisen großen Zuspruch"}, {"kategorie": "", "text": "Die GDVP war im Gegensatz zur [[Christlich-Sozialen]] Partei antiklerikal und stand der katholischen Kirche kritisch gegenüber. Sie vertrat außerdem antisemitische Positionen, was zur Polarisierung der politischen Landschaft beitrug"}, {"kategorie": "", "text": "Die Partei positionierte sich rechts der Mitte und kooperierte zeitweise mit der [[Nationalsozialistischen]] Deutschen Arbeiterpartei (NSDAP), obwohl es auch Differenzen gab. In der Ersten Republik war sie ein Gegengewicht zur sozialdemokratischen Arbeiterbewegung und den christlich-sozialen Kräften"}, {"kategorie": "", "text": "Die GDVP verlor in den 1930er Jahren zunehmend an Bedeutung und wurde schließlich 1934 im Zuge des autoritären [[Ständestaates]] ([[Austrofaschismus]]) aufgelöst. Viele ihrer Anhänger und Mitglieder unterstützten später den Nationalsozialismus und den [[Anschluss]] Österreichs an Deutschland im Jahr 1938"}, {"kategorie": "", "text": "Die Großdeutsche Volkspartei spielte somit eine bedeutende Rolle im politischen Spektrum der Ersten Republik und trug zur Verbreitung nationalistischer und antisemitischer Ideologien in Österreich bei. Ihr Einfluss verblasste jedoch im Laufe der Zeit zugunsten radikalerer Kräfte."}]'::jsonb, ''),
  ('vadroog-von-saint-germain', 'Vadroog von Saint Germain', '', '', '', '', 'Vertrag von Saint Germain', '[{"kategorie": "hist.", "text": "\"Friedensvertrag, der am 10. September 1919 im Schloss von Saint-Germain bei Paris zwischen den Alliierten und der neuen Republik Österreich geschlossen wurde\""}, {"kategorie": "", "text": "Er beendete offiziell den [[Ersten]] Weltkrieg für Österreich und legte die Auflösung der [[Österreichisch-Ungarischen]] Monarchie fest. Der Vertrag hatte weitreichende Konsequenzen für das neu entstandene Österreich, das sich nun auf seine deutschsprachigen Gebiete beschränken musste"}, {"kategorie": "", "text": "Wesentliche Bestimmungen des Vertrags: (i) territoriale Verluste (Österreich musste große Gebiete abtreten, darunter Südtirol und das Trentino an Italien, das Sudetenland an die Tschechoslowakei, die Untersteiermark und Teile Kärntens an das neu gegründete Königreich der Serben, Kroaten und Slowenen [Jugoslawien]. Die dadurch neu definierten Grenzen legten das heutige Territorium Österreichs weitgehend fest;  (ii) Verbot der Vereinigung mit Deutschland (der Vertrag untersagte ausdrücklich die angestrebte Vereinigung mit Deutschland („Anschluss“), die von der Republik Deutsch-Österreich als Option zur wirtschaftlichen Stabilisierung angestrebt wurde. Österreich musste zudem den Namen „Deutsch-Österreich“ aufgeben und sich fortan „Republik Österreich“ nennen);  (iii) militärische Einschränkungen (der Vertrag legte strenge Begrenzungen für das österreichische Militär fest, das auf 30.000 Mann beschränkt wurde, und untersagte das Besitzen schwerer Waffen);  (iv) Reparationszahlungen (Österreich wurde verpflichtet, Reparationszahlungen an die Siegermächte zu leisten, wobei diese im Vergleich zu anderen Nachfolgestaaten der [[Habsburgermonarchie]] verhältnismäßig gering ausfielen)"}, {"kategorie": "", "text": "Der Vertrag von Saint-Germain führte zu erheblichen sozialen und wirtschaftlichen Herausforderungen für Österreich, das sich nun als kleiner Binnenstaat neu orientieren musste. Er wird in Österreich oft als „Diktatfrieden“ bezeichnet, da die Bedingungen ohne Mitsprache des Landes festgelegt wurden und die neue Republik in eine politisch und wirtschaftlich schwierige Lage versetzten."}]'::jsonb, ''),
  ('republik-deitsch-oestarreich', 'Republik Deitsch-Östarreich', '', '', '', '', 'Republik Deutsch-Österreich', '[{"kategorie": "hist.", "text": "\"Name des Staates, der am 12. November 1918 nach dem Zusammenbruch der [[Habsburgermonarchie]] und dem Ende des [[Ersten]] Weltkriegs von der provisorischen Nationalversammlung ausgerufen wurde\""}, {"kategorie": "", "text": "Sie umfasste die deutschsprachigen Gebiete der ehemaligen [[Österreich-Ungarischen]] Monarchie und strebte eine Vereinigung mit dem [[Deutschen]] Reich an, da viele Vertreter davon ausgingen, dass die verbliebenen Gebiete alleine wirtschaftlich und politisch kaum überlebensfähig wären"}, {"kategorie": "", "text": "Die „Republik Deutsch-Österreich“ setzte auf das Selbstbestimmungsrecht der Völker und definierte sich als deutschsprachiger Nationalstaat"}, {"kategorie": "", "text": "Der Vertrag von Saint-Germain (1919), der [[Friedensvertrag]] mit den Siegermächten, untersagte jedoch ausdrücklich die angestrebte Vereinigung mit Deutschland und verpflichtete den neuen Staat, sich „Republik Österreich“ zu nennen. Er legte auch die neuen Grenzen fest, wodurch große deutschsprachige Gebiete wie Südtirol und das Sudetenland bei Italien und der Tschechoslowakei verblieben"}, {"kategorie": "", "text": "Die Republik Deutsch-Österreich bestand somit nur in den ersten Jahren der [[Ersten]] Republik und markierte den Übergang von der [[Monarchie]] zu einer demokratischen Republik, die sich nun auf den Kern des heutigen Österreichs beschränken musste."}]'::jsonb, ''),
  ('englbeat-doifuss', 'Englbeat Doifuss', '', '', '', '', 'Engelbert Dollfuß', '[{"kategorie": "hist.", "text": "\"österreichischer Politiker (1892–1934), der von 1932 bis zu seinem Tod 1934 [[Bundeskanzler]] der [[Ersten]] Republik Österreich war\""}, {"kategorie": "", "text": "Als Mitglied der konservativen [[Christlichsozialen]] Partei führte Dollfuß Österreich durch eine Zeit schwerer politischer und wirtschaftlicher Krisen"}, {"kategorie": "", "text": "Er wurde zum zentralen Vertreter des autoritären [[Ständestaats]] und setzte sich für eine konservativ-katholische und antimarxistische Ordnung ein, die in scharfem Gegensatz zur sozialdemokratischen Bewegung und dem aufkommenden Nationalsozialismus stand"}, {"kategorie": "", "text": "Dollfuß nutzte die politischen Spannungen und die Notverordnungen, um das Parlament 1933 auszuschalten und eine autoritäre Regierung zu etablieren. Er formte die Einheitspartei [[Vaterländische]] Front und begann, das politische System nach dem Modell des „austrofaschistischen“ Ständestaats umzubauen"}, {"kategorie": "", "text": "Seine Politik richtete sich gegen die Sozialdemokraten (was im [[Februaraufstand]] 1934 zur gewaltsamen Auseinandersetzung mit dem sozialdemokratischen [[Schutzbund]] führte) und die Nationalsozialisten, die einen [[Anschluss]] Österreichs an Deutschland anstrebten"}, {"kategorie": "", "text": "Am 25. Juli 1934 wurde Dollfuß bei einem nationalsozialistischen Putschversuch im Bundeskanzleramt in Wien ermordet. Dieser gescheiterte Putschversuch, bekannt als [[Juliputsch]], führte zu seinem Tod und hinterließ Österreich in einer angespannten politischen Situation. Dollfuß’ Tod verstärkte den autoritären Kurs in Österreich, und sein Nachfolger, Kurt Schuschnigg, setzte seine Politik des Ständestaats fort"}, {"kategorie": "", "text": "Engelbert Dollfuß ist eine umstrittene Figur in der österreichischen Geschichte: Während er von einigen als Verteidiger der Unabhängigkeit gegen die Nationalsozialisten gesehen wird, bleibt seine autoritäre Regierungsweise und sein Vorgehen gegen politische Gegner bis heute kritisch diskutiert."}]'::jsonb, ''),
  ('kuat-schuschnigg', 'Kuat Schuschnigg', '', '', '', '', 'Kurt Schuschnigg', '[{"kategorie": "hist.", "text": "\"österreichischer Politiker (1897–1977), der von 1934 bis 1938 [[Bundeskanzler]] der [[Ersten]] Republik Österreich war\""}, {"kategorie": "", "text": "Als Mitglied der konservativen [[Vaterländischen]] Front, der Einheitspartei des autoritären [[Ständestaates]], versuchte er, Österreichs Unabhängigkeit gegenüber dem nationalsozialistischen Deutschland zu wahren"}, {"kategorie": "", "text": "Schuschnigg war Nachfolger von [[Engelbert]] Dollfuß, der 1934 nach einem Putschversuch der österreichischen Nationalsozialisten ermordet worden war"}, {"kategorie": "", "text": "Während seiner Amtszeit verfolgte Schuschnigg eine Politik des autoritären Ständestaates, die auf einer konservativ-katholischen und antimarxistischen Grundlage beruhte. Gleichzeitig stand er unter zunehmendem Druck durch das nationalsozialistische Deutschland unter Adolf Hitler"}, {"kategorie": "", "text": "Schuschniggs Politik war darauf ausgerichtet, Österreichs Eigenständigkeit zu bewahren, was im Juliabkommen von 1936 zunächst einen gewissen Erfolg brachte, indem es Spannungen zwischen Österreich und Deutschland entschärfte"}, {"kategorie": "", "text": "Im Februar 1938 wurde Schuschnigg von Hitler zum sogenannten Berchtesgadener Abkommen gedrängt, das die nationalsozialistische Einflussnahme auf Österreich deutlich verstärkte"}, {"kategorie": "", "text": "Nach einem gescheiterten Versuch, mit einer Volksabstimmung die Unabhängigkeit Österreichs zu sichern, musste Schuschnigg am 11. März 1938 unter massivem Druck zurücktreten, und das Land wurde am darauffolgenden Tag von deutschen Truppen besetzt – der sogenannte [[Anschluss]] Österreichs an das [[Deutsche]] Reich"}, {"kategorie": "", "text": "Nach dem Anschluss wurde Schuschnigg von den Nationalsozialisten inhaftiert und verbrachte mehrere Jahre in Konzentrationslagern, bevor er 1945 befreit wurde. Nach dem Krieg lebte er in den USA und kehrte später nach Österreich zurück, wo er als Autor und Universitätsprofessor tätig war. Schuschniggs Rolle und sein Versuch, Österreichs Unabhängigkeit zu bewahren, machen ihn zu einer komplexen und umstrittenen Figur in der österreichischen Geschichte."}]'::jsonb, ''),
  ('dr-koarl-renna', 'Dr. Koarl Renna', '', '', '', '', 'Dr. Karl Renner', '[{"kategorie": "hist.", "text": "\"bedeutender österreichischer Politiker und Staatsmann (1870–1950), der eine zentrale Rolle in der Gründung und Neugestaltung der österreichischen Republik spielte\""}, {"kategorie": "", "text": "Er war Mitglied der [[Sozialdemokratischen]] Arbeiterpartei (SDAP) und prägte die Politik in Österreich durch seine Rolle als führender Vertreter in entscheidenden historischen Momenten"}, {"kategorie": "", "text": "Renner war maßgeblich an der Gründung der [[Ersten]] Republik Österreich 1918 beteiligt und fungierte als deren erster Staatskanzler. In den Jahren nach dem Ersten Weltkrieg verhandelte er die Bedingungen des Vertrags von Saint-Germain (1919), der Österreich als eigenständigen Staat anerkannte, aber weitreichende Gebietsverluste zur Folge hatte"}, {"kategorie": "", "text": "Nach dem [[Zweiten]] Weltkrieg spielte Renner erneut eine Schlüsselrolle: Er leitete 1945 als [[Bundespräsident]] die provisorische Regierung zur Gründung der [[Zweiten]] Republik Österreich und setzte sich erfolgreich für die Wiederherstellung eines demokratischen Österreichs ein. Dabei förderte er die Zusammenarbeit zwischen den sozialistischen und konservativen Kräften, was zur Bildung der ersten großen Koalition führte und den Grundstein für die Nachkriegsordnung legte"}, {"kategorie": "", "text": "Renner gilt als pragmatischer Politiker und Vordenker, der sich für eine funktionierende Demokratie und die Stabilisierung Österreichs in schwierigen Zeiten einsetzte."}]'::jsonb, ''),
  ('dr-koarl-luega', 'Dr. Koarl Luega', '', '', '', '', 'Dr. Karl Lueger', '[{"kategorie": "hist.", "text": "\"österreichischer Politiker und Bürgermeister von Wien (1844–1910), der die Stadtpolitik im späten 19. und frühen 20. Jahrhundert maßgeblich prägte\""}, {"kategorie": "", "text": "Er war Mitbegründer der [[Christlichsozialen]] Partei und gilt als einer der populärsten, aber auch umstrittensten Politiker seiner Zeit"}, {"kategorie": "", "text": "Lueger modernisierte Wien durch umfangreiche Infrastrukturprojekte, die die Stadtentwicklung nachhaltig beeinflussten, darunter den Ausbau der Wasser- und Energieversorgung sowie des öffentlichen Nahverkehrs. Er setzte sich für Sozialreformen ein und verbesserte die Lebensbedingungen der ärmeren Bevölkerung, was ihm großen Zuspruch verschaffte"}, {"kategorie": "", "text": "Gleichzeitig ist Lueger jedoch eine umstrittene Figur, da er stark antisemitische Rhetorik nutzte, um Wähler für sich zu gewinnen. Sein Antisemitismus war tief in seiner politischen Agenda verankert und beeinflusste die öffentliche Meinung nachhaltig. Diese Haltung und sein manipulativer Politikstil machten ihn zum Vorbild für einige extremistische Strömungen, auch für Adolf Hitler, der Lueger in „Mein Kampf“ als eine seiner Inspirationen nannte"}, {"kategorie": "", "text": "Luegers Erbe ist in Österreich bis heute umstritten. Während seine sozialen Reformen und seine Rolle bei der Modernisierung Wiens anerkannt werden, wird sein Antisemitismus scharf kritisiert."}]'::jsonb, ''),
  ('hochadeliga', 'Hochådeliga', '', '', '', '', 'Hochadeliger', '[{"kategorie": "hist.", "text": "\"Angehöriger des höchsten Adels, der oft über großen politischen Einfluss, beträchtliche Ländereien und besondere Titel verfügte\""}, {"kategorie": "", "text": "Der österreichische Hochadel umfasste die mächtigsten Familien des Landes, darunter [[Erzherzöge]], [[Fürsten]] und [[Grafen]], die oft enge Verbindungen zum Herrscherhaus der [[Habsburger]] hatten oder selbst zur Dynastie gehörten"}, {"kategorie": "", "text": "Hochadelige waren typischerweise in den höchsten gesellschaftlichen und militärischen Positionen vertreten und hatten häufig Einfluss auf die Politik des [[Habsburgerreiches]]"}, {"kategorie": "", "text": "Der Hochadel in Österreich unterschied sich vom niederen Adel durch seine Titel und Privilegien, wie z.B. das Recht, hohe Ämter im Reich zu bekleiden, [[Landtage]] zu dominieren und in der Nähe des [[Kaisers]] bedeutende Rollen einzunehmen"}, {"kategorie": "", "text": "Neben den Habsburgern selbst gehörten Familien wie die Liechtenstein, Kinsky, Esterházy und Schwarzenberg zum österreichischen Hochadel. Diese Familien standen in engem Austausch mit dem Kaiserhof und hatten oft bedeutende Besitztümer und Residenzen in Wien und anderen habsburgischen [[Erblanden]]"}, {"kategorie": "", "text": "Mit dem Ende der [[Monarchie]] und der Abschaffung des Adels 1919 verloren hochadelige Familien ihre politischen Privilegien, behielten jedoch in der Gesellschaft und Kultur Österreichs einen hohen Stellenwert und sind bis heute Teil des kulturellen Erbes."}]'::jsonb, ''),
  ('oestarreichische-bischofskonfarenz', 'Östarreichische Bischofskonfarenz', '', '', '', '', 'Österreichische Bischofskonferenz', '[{"kategorie": "rel.", "text": "\"zentrales Gremium der katholischen [[Bischöfe]] in Österreich\""}, {"kategorie": "", "text": "Sie besteht aus den [[Diözesanbischöfen]] der neun österreichischen Diözesen sowie aus [[Weihbischöfen]] und anderen hochrangigen Geistlichen"}, {"kategorie": "", "text": "Die Bischofskonferenz koordiniert die Arbeit der katholischen Kirche in Österreich und dient als Plattform für gemeinsame Entscheidungen und Stellungnahmen zu religiösen, gesellschaftlichen und politischen Themen"}, {"kategorie": "", "text": "Gegründet 1849 und in ihrer heutigen Form nach dem Zweiten Vatikanischen Konzil (1962–1965) neu organisiert, hat die Bischofskonferenz die Aufgabe, die Zusammenarbeit zwischen den [[Diözesen]] zu fördern und die Einheit der katholischen Kirche in Österreich zu stärken"}, {"kategorie": "", "text": "Sie vertritt die Kirche in öffentlichen Angelegenheiten, formuliert ethische Positionen und ist Ansprechpartnerin für staatliche und gesellschaftliche Institutionen. Der Vorsitzende der Bischofskonferenz ist meist der [[Erzbischof]] von Wien"}, {"kategorie": "", "text": "Die Bischofskonferenz hat auch die Funktion, das Verhältnis zur weltweiten katholischen Kirche, insbesondere zum Heiligen Stuhl, zu pflegen und die Anliegen der österreichischen Kirche im internationalen Kontext einzubringen."}]'::jsonb, ''),
  ('katholische-kiachn', 'Katholische Kiachn', '', '', '', '', 'Katholische Kirche', '[{"kategorie": "rel.", "text": "\"größte christliche Glaubensgemeinschaft des Landes mit einer langen Geschichte, die eng mit der kulturellen und politischen Entwicklung Österreichs verknüpft ist\""}, {"kategorie": "", "text": "Als Teil der weltweiten römisch-katholischen Kirche steht sie unter der geistlichen Leitung des Papstes und ist in mehrere [[Diözesen]] unterteilt, darunter die [[Erzdiözese]] Wien, die Erzdiözese Salzburg und weitere [[Bistümer]] wie Linz, Graz-Seckau und St. Pölten"}, {"kategorie": "", "text": "In Österreich spielt die katholische Kirche eine bedeutende Rolle im religiösen, sozialen und kulturellen Leben. Sie betreibt zahlreiche Schulen, Krankenhäuser, soziale Einrichtungen und engagiert sich stark in der Armen- und Flüchtlingshilfe"}, {"kategorie": "", "text": "Historisch war die Kirche lange Zeit eng mit der [[habsburgischen]] Monarchie verbunden, und der Katholizismus wurde in dieser Zeit zum prägenden Glauben der Bevölkerung"}, {"kategorie": "", "text": "Auch nach der Trennung von Kirche und Staat 1918 behielt die katholische Kirche großen Einfluss und leistet bis heute einen wichtigen Beitrag zur Gesellschaft"}, {"kategorie": "", "text": "Die Kirche in Österreich wird von der [[Österreichischen]] Bischofskonferenz vertreten, die als Bindeglied zur Vatikanstadt und zu anderen katholischen Gemeinschaften weltweit fungiert. Sie engagiert sich in gesellschaftlichen Debatten und setzt sich für ethische Werte in Bereichen wie Bildung, Umwelt und Sozialpolitik ein."}]'::jsonb, ''),
  ('privilegium-minus', 'Privilegium Minus', '', '', '', '', 'Privilegium Minus', '[{"kategorie": "hist.", "text": "\"kaiserliche Urkunde, die 1156 von Kaiser [[Friedrich]] I. Barbarossa ausgestellt wurde und Österreich von einer [[Markgrafschaft]] zu einem [[Herzogtum]] erhob\""}, {"kategorie": "", "text": "Es wurde anlässlich der Belehnung [[Heinrichs]] II. Jasomirgott, des Babenberger-Markgrafen, ausgestellt und gewährte diesem weitreichende Sonderrechte, darunter die Erbfolge in weiblicher Linie und größere Autonomie gegenüber dem [[Kaiser]] des [[Heiligen]] Römischen Reiches"}, {"kategorie": "", "text": "Das Privilegium Minus gilt als Grundlage für die staatliche Eigenständigkeit Österreichs und eine frühe Form des österreichischen Sonderstatus innerhalb des Reiches"}, {"kategorie": "", "text": "Das Dokument sicherte dem neuen Herzogtum eine größere Unabhängigkeit, indem es unter anderem festlegte, dass kaiserliche Truppen nur auf ausdrückliche Einladung des [[Herzogs]] ins Land kommen durften. Zudem wurde die Bindung des Herzogtums an das Reich gelockert, was den Babenbergern die Möglichkeit bot, ihre Herrschaft autonomer und stabiler auszubauen"}, {"kategorie": "", "text": "Das Privilegium Minus blieb über Jahrhunderte ein symbolträchtiges Dokument und wurde später im 14. Jahrhundert von den [[Habsburgern]] durch das [[Privilegium]] Maius ergänzt, das die Rechte und den Status des [[Hauses]] Habsburg weiter stärkte und den Titel à„Erzherzog“ einführte."}]'::jsonb, ''),
  ('moakgrofschoft-ostarrichi', 'Moakgrofschoft Ostarrichi', '', '', '', '', 'Markgrafschaft Ostarrichi', '[{"kategorie": "hist.", "text": "\"mittelalterlicher Vorgänger des heutigen Österreich, der ein Grenzgebiet (eine „Mark“) des Ostfrankenreichs bezeichnete, das später Teil des [[Heiligen]] Römischen Reiches wurde\""}, {"kategorie": "", "text": "Der Begriff à„Ostarrîchi“, erstmals 996 in einer Urkunde erwähnt, bedeutet „östliches Reich“ oder „östliches Gebiet“ und gilt als die älteste bekannte Form des Namens „Österreich“"}, {"kategorie": "", "text": "Die Markgrafschaft entstand im 10. Jahrhundert als Grenzgebiet zum Schutz vor Angriffen aus dem Osten, insbesondere durch ungarische Stämme. Sie wurde den [[Babenbergern]], einer Adelsfamilie, zur Verwaltung und Verteidigung anvertraut. Die Babenberger entwickelten die Mark Ostarrîchi durch strategische Expansion und Förderung des Landes zu einem wichtigen Machtzentrum"}, {"kategorie": "", "text": "Im Jahr 1156 wurde die Markgrafschaft Ostarrîchi durch das [[Privilegium]] Minus von Kaiser [[Friedrich]] I. Barbarossa zum [[Herzogtum]] Österreich erhoben, wodurch es weitreichende Autonomie und die Möglichkeit zur Erbfolge erhielt"}, {"kategorie": "", "text": "Diese Erhebung war ein bedeutender Schritt zur Entwicklung eines unabhängigen österreichischen Staates, der später unter den [[Habsburgern]] weiter ausgebaut wurde und zur Keimzelle des habsburgischen Kaiserreichs wurde."}]'::jsonb, ''),
  ('schlocht-bei-diankruud-und-jednschbeign', 'Schlocht bei Diankruud und Jednschbeign', '', '', '', '', 'Schlacht bei Dürnkrut und Jedenspeigen', '[{"kategorie": "hist.", "text": "\"eine der größten mittelalterlichen Schlachten Mitteleuropas, welche am 26. August 1278 zwischen den heutigen Orten Dürnkrut und Jedenspeigen an der March in Niederösterreich stattfand\""}, {"kategorie": "", "text": "In dieser Schlacht besiegte der römisch-deutsche König [[Rudolf]] I. von Habsburg den böhmischen König Ottokar II. Přemysl"}, {"kategorie": "", "text": "Der Sieg hatte weitreichende Folgen für die Machtverhältnisse im [[Heiligen]] Römischen Reich und legte den Grundstein für die Herrschaft der [[Habsburger]] in Österreich"}, {"kategorie": "", "text": "Nach dem Ende der Staufer-Dynastie kämpften verschiedene Adelsfamilien um die Vorherrschaft im Reich. Rudolf I. wurde 1273 zum römisch-deutschen König gewählt, während Ottokar II. von Böhmen bereits große Teile des heutigen Österreich kontrollierte und selbst Anspruch auf den Kaiserthron erhob"}, {"kategorie": "", "text": "Ottokar II. weigerte sich, Rudolfs Wahl anzuerkennen und die österreichischen [[Herzogtümer]] an Rudolf abzutreten. Dies führte zu einem eskalierenden Konflikt, in dem Rudolf die Rückgabe der Gebiete forderte"}, {"kategorie": "", "text": "Rudolf verbündete sich mit ungarischen Truppen unter König Ladislaus IV. Die Habsburger Truppen sowie ihre Verbündeten standen einer überlegenen böhmischen Armee gegenüber. Die Entscheidung fiel, als die ungarischen Reiter in die Flanken der böhmischen Truppen eindrangen und das Heer Ottokars in die Flucht schlugen. König Ottokar selbst fiel in der Schlacht"}, {"kategorie": "", "text": "Durch den Sieg über Ottokar II. konnte Rudolf die österreichischen Herzogtümer unter die Kontrolle der [[Habsburger]] bringen, die sie über Jahrhunderte behielten und eine der mächtigsten Dynastien Europas wurden"}, {"kategorie": "", "text": "Mit Ottokars Tod verlor das Königreich Böhmen seine Vorherrschaft in Mitteleuropa und musste seine Ansprüche auf Österreich aufgeben"}, {"kategorie": "", "text": "Die Schlacht bei Dürnkrut und Jedenspeigen gilt somit als ein Wendepunkt in der europäischen Geschichte und ein Schlüsselereignis in der Geschichte der Habsburger, die bis 1918 das Schicksal Österreichs und weite Teile Europas bestimmten."}]'::jsonb, ''),
  ('oestarreichische-kaisakrone', 'Östarreichische Kaisakrone', '', '', '', '', 'Österreichische Kaiserkrone', '[{"kategorie": "hist.", "text": "\"Symbol für die höchste monarchische Macht und Autorität eines [[Kaisers]]\""}, {"kategorie": "", "text": "Sie steht als [[Insignie]] für die Herrschaft des [[Kaisers]] über ein [[Kaiserreich]] oder Imperium. Ähnlich wie die [[Königskrone]] für einen [[König]] symbolisiert die Kaiserkrone den Anspruch auf umfassende Macht und Herrschaft, oft über mehrere Königreiche oder Völker"}, {"kategorie": "", "text": "Historisch diente die Kaiserkrone als Zeichen der Legitimation und Autorität eines Kaisers und wurde bei feierlichen Anlässen wie Krönungen oder Staatszeremonien getragen"}, {"kategorie": "", "text": "In der Geschichte Österreichs spielte die [[Österreichische]] Kaiserkrone (auch [[Rudolfskrone]] genannt) eine bedeutende Rolle. Die Rudolfskrone (die Privatkrone Kaiser [[Rudolfs]] II., die für diesen im Jahr 1602 angefertigt wurde) wurde bei Ausrufung des [[Kaisertums]] Österreich durchà Franz II im Jahre 1804 als [[österreichische]] Kaiserkrone  bestimmt"}, {"kategorie": "", "text": "Nachdem er die [[Kaiserkrone]] des [[Heiligen]] Römischen Reiches niedergelegt hatte, nahm [[Franz]] II. den Titel [[Franz I., Kaiser von Österreich]] an und begründete die habsburgische Kaiserlinie in Österreich, die bis zum Ende der [[Monarchie]] 1918 bestand"}, {"kategorie": "", "text": "Die Krone war Teil der [[habsburgischen]] Reichsinsignien und wurde bei offiziellen Anlässen verwendet, um die Herrschaft des [[Kaisers]] darzustellen"}, {"kategorie": "", "text": "In der Wiener [[Schatzkammer]] der Hofburg kann die Krone heute besichtigt werden, wo sie als zentrales Stück der kaiserlichen [[Insignien]] ausgestellt ist. Sie ist ein bedeutendes Symbol für das [[Kaisertum]] Österreich und die lange Herrschaft der [[Habsburgerdynastie]]."}]'::jsonb, ''),
  ('franz-ii', 'Franz II.', '', '', '', '', 'Franz II.', '[{"kategorie": "", "text": "Franz wurde 1792 zum [[Kaiser]] des [[Heiligen]] Römischen Reiches ernannt und regierte in einer Zeit großer Umwälzungen, insbesondere durch den Aufstieg Napoleons und die hieraus resultierenden [[Napoleonischen]] Kriege"}, {"kategorie": "", "text": "Bis 1806 führte Franz den Titel [[Franz II. Kaiser des Heiligen Römischen Reiches]]. Im Jahre 1806, nach Napoleons Sieg über Österreich und Preußen, legte Franz den Titel [[Kaiser des Heiligen Römischen Reiches]] nieder und beendete damit die über 1000-jährige Geschichte des Reiches. Ab diesem Zeitpunkt regierte er ausschließlich als \"Kaiser von Österreich\""}, {"kategorie": "", "text": "Nachdem er 1806 die [[Kaiserkrone]] des [[Heiligen]] Römischen Reiches niedergelegt hatte, nahm [[Franz]] II. den Titel [[Franz I. Kaiser von Österreich]] an und begründete damit die habsburgische Kaiserlinie in Österreich, die bis zum Ende der [[Monarchie]] 1918 bestand"}, {"kategorie": "", "text": "Nach Napoleons Niederlage spielte Franz I. eine wichtige Rolle beim [[Wiener]] Kongress, der die Neuordnung Europas nach den [[Napoleonischen]] Kriegen festlegte. Österreich profitierte territorial von den Verhandlungen und sicherte seine Stellung als Großmacht in Europa"}, {"kategorie": "", "text": "Franz I. war ein konservativer [[Monarch]], der die [[Aufklärung]] und revolutionäre Ideen ablehnte. Er setzte auf eine strikte Politik der [[Restauration]] und des [[Absolutismus]], um die habsburgische Herrschaft zu sichern. Franz I. regierte mit einem starken Netzwerk von Beratern, darunter der einflussreiche Fürst [[Metternich]], der die konservative Politik der [[Habsburger]] prägte"}]'::jsonb, ''),
  ('franz-i', 'Franz I.', '', '', '', '', 'Franz I.', '[{"kategorie": "", "text": "Franz wurde 1792 zum [[Kaiser]] des [[Heiligen]] Römischen Reiches ernannt und regierte in einer Zeit großer Umwälzungen, insbesondere durch den Aufstieg Napoleons und die hieraus resultierenden [[Napoleonischen]] Kriege"}, {"kategorie": "", "text": "Bis 1806 führte Franz den Titel [[Franz II. Kaiser des Heiligen Römischen Reiches]]. Im Jahre 1806, nach Napoleons Sieg über Österreich und Preußen, legte Franz den Titel [[Kaiser des Heiligen Römischen Reiches]] nieder und beendete damit die über 1000-jährige Geschichte des Reiches. Ab diesem Zeitpunkt regierte er ausschließlich als \"Kaiser von Österreich\""}, {"kategorie": "", "text": "Nachdem er 1806 die [[Kaiserkrone]] des [[Heiligen]] Römischen Reiches niedergelegt hatte, nahm [[Franz]] II. den Titel [[Franz I. Kaiser von Österreich]] an und begründete damit die habsburgische Kaiserlinie in Österreich, die bis zum Ende der [[Monarchie]] 1918 bestand"}, {"kategorie": "", "text": "Nach Napoleons Niederlage spielte Franz I. eine wichtige Rolle beim [[Wiener]] Kongress, der die Neuordnung Europas nach den [[Napoleonischen]] Kriegen festlegte. Österreich profitierte territorial von den Verhandlungen und sicherte seine Stellung als Großmacht in Europa"}, {"kategorie": "", "text": "Franz I. war ein konservativer [[Monarch]], der die [[Aufklärung]] und revolutionäre Ideen ablehnte. Er setzte auf eine strikte Politik der [[Restauration]] und des [[Absolutismus]], um die habsburgische Herrschaft zu sichern. Franz I. regierte mit einem starken Netzwerk von Beratern, darunter der einflussreiche Fürst [[Metternich]], der die konservative Politik der [[Habsburger]] prägte"}]'::jsonb, ''),
  ('mettanich-system', 'Mettanich-System', '', '', '', '', 'Metternich-System', '[{"kategorie": "hist.", "text": "\"politisches und diplomatisches System, das der österreichische Staatsmann Fürst Klemens Wenzel von [[Metternich]] im 19. Jahrhundert entwickelte und prägte\""}, {"kategorie": "", "text": "Es war maßgeblich durch seine konservative und restaurative Politik geprägt, die darauf abzielte, die [[Monarchien]] in Europa nach den [[Napoleonischen]] Kriegen zu stabilisieren und die Errungenschaften der [[Französischen]] Revolution rückgängig zu machen"}, {"kategorie": "", "text": "Um dieses System zu stabilisieren, setzte Metternich auf internationale Zusammenarbeit. Die [[Heilige]] Allianz (zwischen Russland, Preußen und Österreich) und die [[Quadrupelallianz]] (mit Großbritannien) wurden gegründet, um die Monarchien zu stützen und revolutionäre Bewegungen in Europa zu bekämpfen. Diese Allianzen dienten als Instrumente zur Sicherung der konservativen Ordnung"}, {"kategorie": "", "text": "In den von Metternich beeinflussten Staaten wurden strenge Zensurmaßnahmen ergriffen, um revolutionäre Ideen und liberales Gedankengut zu unterdrücken. Die Geheimdienste und Polizei wurden ausgebaut, um politische Gegner zu überwachen und Aufstände zu verhindern"}, {"kategorie": "", "text": "Als Architekt des [[Wiener]] Kongresses spielte Metternich eine Schlüsselrolle bei der Neuordnung Europas nach dem Sturz [[Napoleons]]. Die Beschlüsse des Wiener Kongresses zementierten die monarchischen Herrschaften und verhinderten größere territoriale Veränderungen, die revolutionäre Bewegungen hätten fördern können."}]'::jsonb, ''),
  ('franzoesische-revolution', 'Französische Revolution', '', '', '', '', 'Französische Revolution', '[{"kategorie": "allg.", "text": "\"einschneidendes Ereignis in der europäischen Geschichte, das die politischen und sozialen Strukturen Frankreichs radikal veränderte und weitreichende Auswirkungen auf ganz Europa hatte, einschließlich Österreich\""}, {"kategorie": "", "text": "Ihr Ziel war es, das absolute [[Königtum]] zu stürzen, eine demokratische Republik zu errichten und Grundrechte wie Freiheit, Gleichheit und Brüderlichkeit durchzusetzen"}, {"kategorie": "", "text": "Die revolutionären Ideale der Französischen Revolution stellten eine direkte Bedrohung für die monarchischen Systeme in Europa dar, insbesondere für Österreich, das eine zentrale Rolle im [[Heiligen]] Römischen Reich spielte"}, {"kategorie": "", "text": "Ab 1792 kam es zu einer Reihe von Kriegen, den sogenannten [[Koalitionskriegen]], in denen Österreich zusammen mit anderen monarchistischen Mächten wie Preußen, Russland und Großbritannien gegen das revolutionäre Frankreich kämpfte. Der Erste Koalitionskrieg (1792–1797) endete für Österreich mit erheblichen Gebietsverlusten im [[Frieden]] von Campo Formio (1797), in dem Österreich die österreichischen Niederlande (das heutige Belgien) und Teile Norditaliens an Frankreich abtreten musste."}, {"kategorie": "", "text": "Die Niederlagen der österreichischen Truppen gegen die französischen Armeen, besonders unter [[Napoleon]] Bonaparte, führten zu großen Gebietsverlusten und politischen Veränderungen. Der [[Frieden]] von Lunéville (1801) bestätigte diese Verluste und zwang Österreich, den linksrheinischen Teil des Heiligen Römischen Reiches an Frankreich abzutreten"}, {"kategorie": "", "text": "Im [[Frieden]] von Pressburg (1805), nach der entscheidenden Niederlage Österreichs in der [[Schlacht]] bei Austerlitz, musste Österreich weitere Gebiete in Italien und Süddeutschland an Frankreich abgeben. Dies schwächte Österreichs Stellung erheblich"}, {"kategorie": "", "text": "Eine der gravierendsten Auswirkungen der Französischen Revolution und der anschließenden [[Napoleonischen]] Kriege war das Ende des [[Heiligen]] Römischen Reiches. Der österreichische Kaiser [[Franz]] II. legte 1806 die [[Kaiserkrone]] des Heiligen Römischen Reiches nieder und erklärte das Reich für aufgelöst. Dies war eine direkte Folge des Drucks durch Napoleon, der 1804 das Kaiserreich Frankreich ausgerufen hatte und die deutsche und österreichische Macht durch die Gründung des Rheinbundes unter französischem Einfluss schwächte"}, {"kategorie": "", "text": "Franz II. nahm daraufhin den Titel [[Franz I. Kaiser von Österreich]] an, wodurch das [[Kaisertum]] Österreich als neue zentrale Machtstruktur des [[Habsburgerreiches]] etabliert wurde."}]'::jsonb, ''),
  ('napoleonische-heaschoft', 'Napoleonische Heaschoft', '', '', '', '', 'Napoleonische Herrschaft', '[{"kategorie": "hist.", "text": "\"Zeit, in der [[Napoleon]] Bonaparte als Konsul und später als Kaiser Frankreichs eine dominierende Rolle in der europäischen Politik spielte\""}, {"kategorie": "", "text": "Für Österreich, eine der führenden Mächte Europas, hatte Napoleons Aufstieg tiefgreifende und weitreichende Auswirkungen. Diese Zeit war geprägt von wiederholten militärischen Konflikten, territorialen Veränderungen und politischen Umbrüchen, die die Machtstellung der [[Habsburgermonarchie]] nachhaltig beeinflussten (siehe \"Koalitionskriege\")"}, {"kategorie": "", "text": "Trotz der wiederholten Niederlagen spielte Österreich eine entscheidende Rolle beim Sturz [[Napoleons]]. 1813 trat es der [[Sechsten]] Koalition bei und kämpfte in der [[Schlacht]] bei Leipzig (1813), auch bekannt als [[Völkerschlacht]], die als einer der entscheidenden Wendepunkte in den [[Napoleonischen]] Kriegen gilt. Der österreichische Feldmarschall Karl Philipp Fürst zu [[Schwarzenberg]] führte die alliierten Truppen in dieser Schlacht zum Sieg"}, {"kategorie": "", "text": "Durch die Niederlage Napoleons und die Beschlüsse des [[Wiener]] Kongresses konnte Österreich einige der verlorenen Gebiete zurückgewinnen. Es erhielt Venetien, Teile Norditaliens und Dalmatien zurück und etablierte sich wieder als führende Macht im neuen [[Deutschen]] Bund, einem lockeren Zusammenschluss deutscher Staaten unter österreichischer Führung."}]'::jsonb, ''),
  ('wiina-kongressbeschluesse', 'Wiina Kongressbeschlüsse', '', '', '', '', 'Wiener Kongressbeschlüsse', '[{"kategorie": "hist.", "text": "\"Beschlüsse des [[Wiener]] Kongresses, der von 1814 bis 1815 stattfand und die politische Neuordnung Europas nach den [[Napoleonischen]] Kriegen zum Ziel hatte\""}, {"kategorie": "", "text": "Vertreter der europäischen Großmächte – insbesondere Österreich, Preußen, Russland und Großbritannien – sowie zahlreiche weitere Staaten verhandelten über territoriale und politische Fragen, um ein langfristiges Gleichgewicht der Kräfte und Stabilität in Europa zu schaffen"}, {"kategorie": "", "text": "Wichtige Beschlüsse des Wiener Kongresses:  (i) Restauration und Legitimität: Die Wiedereinsetzung der alten [[Monarchien]], die durch die [[Französische]] Revolution und [[Napoleon]] abgesetzt worden waren. Legitimität und Monarchie galten als Grundlagen für die Stabilität der Staaten;  (ii) Neuordnung der Grenzen: Die Gebiete wurden so aufgeteilt, dass ein Gleichgewicht der Macht erreicht wurde. Beispielsweise erhielt Preußen große Teile Polens und Sachsens, während Österreich die Kontrolle über Teile Norditaliens wie die Lombardei und Venetien erlangte;  (iii) [[Heilige]] Allianz: Russland, Österreich und Preußen schlossen sich zu einem Bündnis zusammen, um monarchische Prinzipien zu verteidigen und revolutionäre Bewegungen zu unterdrücken;  (iv) [[Deutscher]] Bund: Der Deutsche Bund, ein lockerer Zusammenschluss deutscher [[Fürstentümer]] und [[Königreiche]] unter österreichischem Vorsitz, wurde gegründet. Dieser Bund ersetzte das [[Heilige]] Römische Reich und sollte als Sicherheitsstruktur für Mitteleuropa dienen;  (v) Neutralität der Schweiz: Die dauerhafte Neutralität der Schweiz wurde anerkannt und international garantiert, was die heutige schweizerische Neutralitätspolitik begründete"}, {"kategorie": "", "text": "Die Wiener Kongressbeschlüsse sollten die europäische Friedensordnung sichern und ein Gleichgewicht schaffen, das die Vormachtstellung einzelner Mächte verhinderte. Die Ordnung, die im Wiener Kongress geschaffen wurde, prägte Europa für mehrere Jahrzehnte und gilt als Grundlage für die relativ stabile Phase des „Europäischen Konzertes“ im 19. Jahrhundert."}]'::jsonb, ''),
  ('friidn-von-campo-formio', 'Friidn von Campo Formio', '', '', '', '', 'Frieden von Campo Formio', '[{"kategorie": "hist.", "text": "\"Friedensvertrag, der am 17. Oktober 1797 zwischen Frankreich, vertreten durch [[Napoleon]] Bonaparte, und dem [[Habsburgerreich]] (Österreich) geschlossen wurde\""}, {"kategorie": "", "text": "Der Vertrag beendete den ersten [[Koalitionskrieg]] und markierte einen wichtigen Sieg für das revolutionäre Frankreich"}, {"kategorie": "", "text": "Inhaltlich regelte der Frieden von Campo Formio eine umfangreiche Neuordnung Europas, die vor allem Italien und das Heilige Römische Reich betraf:  (i) Gebietsgewinne für Frankreich: Österreich erkannte die von Frankreich eroberten \"linksrheinischen Gebiete\" an. Damit kontrollierte Frankreich nun das Gebiet westlich des Rheins, was später im [[Wiener]] Kongress (1815) dauerhaft bestätigt wurde;  (ii) Auflösung der Republik Venedig: Venedig und seine Territorien wurden aufgelöst und aufgeteilt. Österreich erhielt die Kontrolle über Venedig und Teile der venezianischen Gebiete in Italien und Dalmatien, um die eigenen Verluste auszugleichen;  (iii) Gründung der Cisalpinischen Republik: Frankreich gründete in Norditalien die Cisalpinische Republik, einen französischen Satellitenstaat, der das revolutionäre Modell Frankreichs widerspiegelte"}, {"kategorie": "", "text": "Der Frieden von Campo Formio gilt als einer der ersten großen diplomatischen Erfolge Napoleons und zeigte seine Fähigkeit, Europa nach den Vorstellungen des revolutionären Frankreichs neu zu ordnen. Der Vertrag hielt jedoch nicht lange: Schon zwei Jahre später brach der Zweite [[Koalitionskrieg]] aus, da die europäischen Mächte versuchten, die französische Expansion erneut einzudämmen."}]'::jsonb, ''),
  ('friidn-von-luneville', 'Friidn von Lunéville', '', '', '', '', 'Frieden von Lunéville', '[{"kategorie": "hist.", "text": "\"Friedensvertrag, der am 9. Februar 1801 zwischen Frankreich und dem [[Heiligen]] Römischen Reich, vertreten durch Kaiser [[Franz]] II. (Österreich), unterzeichnet wurde\""}, {"kategorie": "", "text": "Dieser Friedensvertrag beendete den Zweiten [[Koalitionskrieg]] (1798–1801) und bestätigte die territorialen und politischen Veränderungen, die das revolutionäre Frankreich in Europa angestrebt hatte"}, {"kategorie": "", "text": "Wesentliche Bestimmungen des Friedens von Lunéville:  (i) Anerkennung französischer Gebietsgewinne: Frankreich erhielt die linksrheinischen Gebiete des [[Heiligen]] Römischen Reichs dauerhaft zugesprochen. Damit wurden alle deutschen Gebiete westlich des Rheins offiziell französisch;  (ii) Neuordnung des Heiligen Römischen Reiches: Der Vertrag sah die Entschädigung der Fürsten vor, die linksrheinische Territorien an Frankreich verloren hatten. Dies führte zu umfangreichen Gebietsreformen und Säkularisierungen im Reich, die später im Reichsdeputationshauptschluss (1803) formalisiert wurden;  (iii) Bestätigung der italienischen Republiken: Die französischen Satellitenstaaten in Italien, insbesondere die Cisalpinische Republik und die Ligurische Republik, wurden von Österreich anerkannt. Frankreich festigte dadurch seine Dominanz in Norditalien;  (iv) Ende des Konflikts mit Österreich: Österreich, das innerhalb des Heiligen Römischen Reiches dominierte, akzeptierte die französische Vorherrschaft in großen Teilen Mitteleuropas und Italiens"}, {"kategorie": "", "text": "Der Frieden von Lunéville setzte die Entwicklungen des [[Friedens]] von Campo Formio (1797) fort und stärkte Frankreichs Stellung in Europa weiter. Der Vertrag hatte tiefgreifende Folgen für das [[Heilige]] Römische Reich, das nach dem Verlust der linksrheinischen Gebiete und der bevorstehenden Auflösung und Säkularisation erheblich geschwächt wurde."}]'::jsonb, ''),
  ('friidn-von-pressbuag', 'Friidn von Pressbuag', '', '', '', '', 'Frieden von Pressburg', '[{"kategorie": "hist.", "text": "\"mehrere Friedensverträge, die zwischen 1491 und 1805 in Pressburg (dem heutigen Bratislava) abgeschlossen wurden\""}, {"kategorie": "", "text": "Der bekannteste dieser Verträge ist jedoch der Vertrag von 1805, der am Ende des Dritten [[Koalitionskrieges]] während der [[Napoleonischen]] Kriege geschlossen wurde"}, {"kategorie": "", "text": "Nach der Niederlage der österreichischen und russischen Truppen in der [[Schlacht]] bei Austerlitz am 2. Dezember 1805 musste Österreich unter Kaiser [[Franz]] II. dem überlegenen napoleonischen Frankreich Frieden anbieten"}, {"kategorie": "", "text": "Der Vertrag wurde am 26. Dezember 1805 in Pressburg zwischen Kaiser Napoleon I. von Frankreich und Kaiser Franz II. von Österreich unterzeichnet, wobei Österreich umfangreiche Gebietsabtretungen vornehmen musste: Bayern und Württemberg, beide Verbündete Napoleons, erhielten große Teile der österreichischen Gebiete in Schwaben und Tirol.\nDas Großherzogtum Toskana wurde Napoleon unterstellt und später an seinen Bruder, Ludwig Bonaparte, vergeben. Venedig und Dalmatien wurden ebenfalls Österreich entzogen und an das von Napoleon gegründete Königreich Italien angeschlossen"}, {"kategorie": "", "text": "Der Vertrag von Pressburg schwächte das [[Habsburgerreich]] und markierte das Ende des [[Heiligen]] Römischen Reiches Deutscher Nation, das bald darauf (1806) formell aufgelöst wurde"}, {"kategorie": "", "text": "Kaiser Franz II. legte seine Krone nieder und konzentrierte sich auf das neu gegründete [[Kaisertum]] Österreich. Bayern und Württemberg wurden von Napoleon zu [[Königreichen]] erhoben, was die politische Neuordnung Mitteleuropas unter französischem Einfluss vorantrieb"}, {"kategorie": "", "text": "Der Frieden von Pressburg war ein bedeutender Meilenstein in den [[Napoleonischen]] Kriegen. Er festigte Napoleons Macht und führte zu einer Umgestaltung der politischen Landkarte Europas, die noch bis zum Wiener Kongress 1815 spürbar war."}]'::jsonb, ''),
  ('friidn-von-schoenbrunn', 'Friidn von Schönbrunn', '', '', '', '', 'Frieden von Schönbrunn', '[{"kategorie": "hist.", "text": "\"Friedensvertrag, der am 14. Oktober 1809 zwischen dem [[Kaisertum]] Österreich und dem Französischen Kaiserreich unter [[Napoleon]] Bonaparte geschlossen wurde (auch als [[Friede]] von Wien bekannt)\""}, {"kategorie": "", "text": "Der Vertrag beendete den Fünften Koalitionskrieg, in dem Österreich vergeblich versucht hatte, Napoleons Vormachtstellung in Europa zu brechen"}, {"kategorie": "", "text": "Im Jahr 1809 begann Österreich unter Kaiser [[Franz]] I. erneut einen Krieg gegen Napoleon, unterstützt von nationalistischen Bewegungen innerhalb der eigenen Bevölkerung, die die napoleonische Herrschaft ablehnten. Trotz anfänglicher Erfolge, wie dem Sieg in der [[Schlacht]] bei Aspern-Essling, unterlag das österreichische Heer schließlich Napoleons Truppen in der entscheidenden [[Schlacht]] bei Wagram im Juli 1809"}, {"kategorie": "", "text": "Der Friedensvertrag wurde im Schloss Schönbrunn in Wien unterzeichnet. Napoleon setzte Österreich harte Friedensbedingungen, um seine Position zu sichern und weitere Kriege in Mitteleuropa zu verhindern"}, {"kategorie": "", "text": "Österreich musste große Gebiete abtreten, darunter: (i) Salzburg und Teile Oberösterreichs fielen an das Königreich Bayern;  (ii) Westgalizien wurde an das Herzogtum Warschau gegeben, das unter Napoleons Protektorat stand;  (iii) Krain, Kärnten und Küstenland gingen an die Illyrischen Provinzen, die von Frankreich kontrolliert wurden"}, {"kategorie": "", "text": "Diese Gebietsverluste schwächten Österreich territorial und wirtschaftlich erheblich. Der Vertrag stellte Österreichs wirtschaftliche und politische Macht stark infrage und schränkte seine Unabhängigkeit weiter ein. Auch war Österreich gezwungen, sich der Kontinentalsperre gegen Großbritannien anzuschließen, was seine Handelsmöglichkeiten einschränkte"}, {"kategorie": "", "text": "Österreichs Adel und die Bevölkerung empfanden die Bedingungen als demütigend, was den Unmut gegen die französische Vorherrschaft in Europa weiter verstärkte"}, {"kategorie": "", "text": "Ein weiteres wichtiges Element des Friedens von Schönbrunn war die Ehe zwischen Napoleon und der österreichischen [[Erzherzogin]] Marie Louise, die im Jahr darauf, 1810, geschlossen wurde. Napoleon versuchte durch diese dynastische Verbindung, seine Position und den Frieden mit Österreich zu festigen und seine Dynastie in Europa zu legitimieren"}, {"kategorie": "", "text": "Der Frieden von Schönbrunn schwächte das [[Habsburgerreich]] weiter und sicherte Napoleons Vormachtstellung in Europa zumindest vorübergehend. Der Vertrag führte zu einer Phase relativer Ruhe, bis sich Österreich 1813 wieder gegen Napoleon stellte, was schließlich zum Sturz Napoleons und zur Neuordnung Europas auf dem [[Wiener]] Kongress 1815 beitrug."}]'::jsonb, ''),
  ('friidn-von-wiin', 'Friidn von Wiin', '', '', '', '', 'Frieden von Wien', '[{"kategorie": "hist.", "text": "\"Friedensvertrag, der am 14. Oktober 1809 zwischen dem [[Kaisertum]] Österreich und dem Französischen Kaiserreich unter [[Napoleon]] Bonaparte geschlossen wurde (auch als [[Frieden]] von Schönbrunn bekannt)\""}, {"kategorie": "", "text": "Der Vertrag beendete den Fünften Koalitionskrieg, in dem Österreich vergeblich versucht hatte, Napoleons Vormachtstellung in Europa zu brechen"}, {"kategorie": "", "text": "Im Jahr 1809 begann Österreich unter Kaiser [[Franz]] I. erneut einen Krieg gegen Napoleon, unterstützt von nationalistischen Bewegungen innerhalb der eigenen Bevölkerung, die die napoleonische Herrschaft ablehnten. Trotz anfänglicher Erfolge, wie dem Sieg in der [[Schlacht]] bei Aspern-Essling, unterlag das österreichische Heer schließlich Napoleons Truppen in der entscheidenden [[Schlacht]] bei Wagram im Juli 1809"}, {"kategorie": "", "text": "Der Friedensvertrag wurde im Schloss Schönbrunn in Wien unterzeichnet. Napoleon setzte Österreich harte Friedensbedingungen, um seine Position zu sichern und weitere Kriege in Mitteleuropa zu verhindern"}, {"kategorie": "", "text": "Österreich musste große Gebiete abtreten, darunter: (i) Salzburg und Teile Oberösterreichs fielen an das Königreich Bayern;  (ii) Westgalizien wurde an das Herzogtum Warschau gegeben, das unter Napoleons Protektorat stand;  (iii) Krain, Kärnten und Küstenland gingen an die Illyrischen Provinzen, die von Frankreich kontrolliert wurden"}, {"kategorie": "", "text": "Diese Gebietsverluste schwächten Österreich territorial und wirtschaftlich erheblich. Der Vertrag stellte Österreichs wirtschaftliche und politische Macht stark infrage und schränkte seine Unabhängigkeit weiter ein. Auch war Österreich gezwungen, sich der Kontinentalsperre gegen Großbritannien anzuschließen, was seine Handelsmöglichkeiten einschränkte"}, {"kategorie": "", "text": "Österreichs Adel und die Bevölkerung empfanden die Bedingungen als demütigend, was den Unmut gegen die französische Vorherrschaft in Europa weiter verstärkte"}, {"kategorie": "", "text": "Ein weiteres wichtiges Element des Friedens von Wien war die Ehe zwischen Napoleon und der österreichischen [[Erzherzogin]] Marie Louise, die im Jahr darauf, 1810, geschlossen wurde. Napoleon versuchte durch diese dynastische Verbindung, seine Position und den Frieden mit Österreich zu festigen und seine Dynastie in Europa zu legitimieren"}, {"kategorie": "", "text": "Der Frieden von Wien schwächte das [[Habsburgerreich]] weiter und sicherte Napoleons Vormachtstellung in Europa zumindest vorübergehend. Der Vertrag führte zu einer Phase relativer Ruhe, bis sich Österreich 1813 wieder gegen Napoleon stellte, was schließlich zum Sturz Napoleons und zur Neuordnung Europas auf dem [[Wiener]] Kongress 1815 beitrug."}]'::jsonb, ''),
  ('schlocht-bei-aspan', 'Schlocht bei Aspan', '', '', '', '', 'Schlacht bei Aspern', '[{"kategorie": "hist.", "text": "\"entscheidende Schlacht (auch bekannt als Schlacht bei Aspern-Essling), welche am 21. und 22. Mai 1809 während des Fünften [[Koalitionskriegs]] zwischen den napoleonischen Truppen und dem [[Kaisertum]] Österreich geschlöagen wurde\""}, {"kategorie": "", "text": "Hierbei erlitt [[Napoleon]] Bonaparte seine erste bedeutende Niederlage auf dem Schlachtfeld, was die Legende seiner militärischen Unbesiegbarkeit ins Wanken brachte"}, {"kategorie": "", "text": "Nach seiner siegreichen Kampagne von 1805 und der Unterzeichnung des [[Friedens]] von Pressburg versuchte Napoleon, seine Vormachtstellung in Mitteleuropa auszubauen. Im Jahr 1809 stellte sich Österreich jedoch erneut gegen ihn, was zum Fünften [[Koalitionskrieg]] führte"}, {"kategorie": "", "text": "Österreich unter Kaiser [[Franz]] I. plante, Napoleon zu besiegen, indem es die Stimmung in den besetzten deutschen Gebieten ausnutzte, die zunehmend gegen die französische Besatzung opponierten"}, {"kategorie": "", "text": "Die Schlacht fand in den Dörfern [[Aspern]] und [[Essling]] am Ostufer der [[Donau]] nahe Wien statt. Napoleon versuchte, mit seiner Grande Armée die Donau zu überqueren, um die österreichische Armee unter [[Erzherzog]] Karl in der Nähe von Wien zu besiegen"}, {"kategorie": "", "text": "Napoleons Truppen waren stark und gut organisiert, doch die Überquerung der Donau stellte ein logistisches Problem dar, da die Brücke aus Booten bestand, die von der österreichischen Armee mehrfach angegriffen wurde"}, {"kategorie": "", "text": "Erzherzog Karl führte die österreichischen Truppen und nutzte Napoleons Schwierigkeiten beim Donauübergang strategisch aus. Durch ständige Angriffe auf die Brücke und gezielte Manöver konnte Karl die Versorgung und Verstärkung der französischen Truppen unterbinden"}, {"kategorie": "", "text": "Am ersten Tag, dem 21. Mai, war Napoleon optimistisch, die Schlacht für sich entscheiden zu können, da er zunächst große Erfolge erzielte und Aspern einnahm. Doch am zweiten Tag griff Erzherzog Karl jedoch erneut an, wobei er sich die Probleme der französischen Versorgung zunutze machte. Die Österreicher führten entschlossene Gegenangriffe, und Karl konnte Essling erobern, was die Franzosen in eine strategisch unvorteilhafte Position brachte. Schließlich war Napoleon gezwungen, sich zurückzuziehen, da die Brücke über die Donau zerstört wurde und die Nachschubwege unterbrochen waren"}, {"kategorie": "", "text": "Die Schlacht endete mit einem taktischen Sieg für die österreichische Armee und brachte Napoleon eine seiner ersten großen Niederlagen. Rund 40.000 Soldaten verloren ihr Leben oder wurden verwundet, was die Schlacht zu einer der blutigsten Auseinandersetzungen der [[Napoleonischen]] Kriege machte"}]'::jsonb, ''),
  ('schlocht-bei-austalitz', 'Schlocht bei Austalitz', '', '', '', '', 'Schlacht bei Austerlitz', '[{"kategorie": "hist.", "text": "\"Schlacht, welche am 2. Dezember 1805 nahe der mährischen Stadt Austerlitz (heute Slavkov u Brna in Tschechien) stattfand (auch bekannt als die [[Dreikaiserschlacht]])\""}, {"kategorie": "", "text": "In dieser Schlacht besiegte Napoleon Bonaparte die verbündeten Armeen des Russischen Zaren Alexander I. und des Österreichischen Kaisers [[Franz]] II. Die Schlacht gilt als eines der brillantesten militärischen Manöver Napoleons und markiert einen Höhepunkt seiner militärischen Karriere"}, {"kategorie": "", "text": "Die Schlacht bei Austerlitz war Teil des Dritten Koalitionskrieges (1805–1806), in dem Großbritannien, Russland, und Österreich ein Bündnis gegen das aufstrebende napoleonische Frankreich geschlossen hatten"}, {"kategorie": "", "text": "Napoleon hatte etwa 73.000 Soldaten zur Verfügung, während die alliierten Armeen, bestehend aus russischen und österreichischen Truppen, rund 85.000 Mann umfassten. Obwohl zahlenmäßig unterlegen, war die französische Armee besser organisiert, und Napoleon nutzte die geografischen Gegebenheiten und das Überraschungsmoment geschickt zu seinem Vorteil"}, {"kategorie": "", "text": "Napoleon täuschte eine Schwäche vor und zog seine Truppen so zurück, dass die Alliierten dachten, sie hätten einen strategischen Vorteil. Er lockte die gegnerischen Truppen in eine verwundbare Position, indem er den Pratzenberg, ein zentrales Plateau, zunächst aufgab. Die Alliierten nahmen den Köder und griffen diesen vermeintlichen Schwachpunkt an"}, {"kategorie": "", "text": "Napoleon nutzte daraufhin seine Reservetruppen und griff die Mitte der Alliierten auf dem Pratzenberg unerwartet an, durchbrach ihre Linien und spaltete die Koalitionsarmee in zwei Hälften"}, {"kategorie": "", "text": "Die französische Armee schlug die Alliierten zurück, und die Schlacht endete mit einer vernichtenden Niederlage für die russisch-österreichischen Truppen, die in Unordnung flohen. Die Alliierten verloren rund 36.000 Mann, darunter Tote, Verwundete und Gefangene, während die französischen Verluste auf etwa 9.000 Mann geschätzt werden"}, {"kategorie": "", "text": "Die Niederlage führte zur Auflösung der Dritten Koalition und zwang Österreich zum [[Frieden]] von Pressburg (26. Dezember 1805), wodurch Österreich erhebliche Gebiete und Einfluss verlor"}, {"kategorie": "", "text": "Das [[Heilige]] Römische Reich löste sich im folgenden Jahr (1806) auf, und Napoleon stieg zum unangefochtenen Herrscher über weite Teile Europas auf"}, {"kategorie": "", "text": "Zusammengefasst war die Schlacht bei Austerlitz ein entscheidender Sieg für Napoleon, der durch seine taktische Genialität gelang. Sie stärkte Frankreichs Position in Europa erheblich und führte zu einer geopolitischen Neuordnung, die die europäischen Mächte nachhaltig beeinflusste."}]'::jsonb, ''),
  ('schlocht-bei-leipzig', 'Schlocht bei Leipzig', '', '', '', '', 'Schlacht bei Leipzig', '[{"kategorie": "hist.", "text": "\"Schlacht, welche vom 16. bis 19. Oktober 1813 stattfand und die größte Schlacht der [[Napoleonischen]] Kriege war (auch als \"Völkerschlacht\" bekannt)"}, {"kategorie": "", "text": "Die Schlacht endete mit einer Niederlage Napoleons und führte letztlich zum Ende seiner Vorherrschaft in Europa"}, {"kategorie": "", "text": "Die Schlacht bei Leipzig war Teil der [[Befreiungskriege]], bei denen sich Österreich, Preußen, Russland und Schweden gegen die französische Herrschaft stellten. Nach Napoleons gescheitertem Russlandfeldzug 1812 wollten die Koalitionsmächte Frankreich aus Deutschland vertreiben"}, {"kategorie": "", "text": "Auf der einen Seite stand Napoleons Armee mit etwa 185.000 Soldaten; auf der anderen die Koalition mit rund 320.000 Soldaten aus Österreich, Preußen, Russland und Schweden"}, {"kategorie": "", "text": "Die Kämpfe dauerten vier Tage und waren heftig. Die Koalitionsarmeen griffen Napoleons Truppen aus mehreren Richtungen an. Napoleon verteidigte sich zunächst erfolgreich, doch die zahlenmäßige Überlegenheit der Koalition zwang ihn letztlich zum Rückzug"}, {"kategorie": "", "text": "Die Schlacht war äußerst blutig, mit insgesamt rund 90.000 Toten und Verwundeten. Die Verluste führten zu einem erheblichen Schwächungseffekt für Napoleons Armee"}, {"kategorie": "", "text": "Die Niederlage zwang Napoleon zum Rückzug aus Deutschland und bereitete den Weg für den Einmarsch der Koalitionstruppen nach Frankreich. Die Schlacht bei Leipzig leitete das Ende von Napoleons Herrschaft ein und führte 1814 zu seiner Abdankung und Exilierung nach Elba."}]'::jsonb, ''),
  ('schlocht-bei-wagram', 'Schlocht bei Wagram', '', '', '', '', 'Schlacht bei Wagram', '[{"kategorie": "hist.", "text": "\"Schlacht, welche fand am 5. und 6. Juli 1809 während des Fünften Koalitionskrieges zwischen den Truppen des französischen Kaisers [[Napoleon]] Bonaparte und der österreichischen Armee unter [[Erzherzog]] Karl von Österreich stattfand\""}, {"kategorie": "", "text": "Sie war eine der größten und blutigsten Schlachten der [[Napoleonischen]] Kriege und endete mit einem Sieg für Napoleon, der damit seine Vorherrschaft über Mitteleuropa behaupten konnte"}, {"kategorie": "", "text": "Nach der [[Schlacht]] bei Aspern-Essling im Mai 1809, in der Napoleon seine erste große Niederlage erlitten hatte, plante er einen Gegenangriff, um Österreich endgültig zu besiegen und seinen Einfluss auf Mitteleuropa zu sichern. Beide Armeen sammelten ihre Kräfte und verstärkten sich in den folgenden Wochen, wobei Napoleon zusätzliche Truppen aus Deutschland und Italien mobilisierte"}, {"kategorie": "", "text": "Die Schlacht fand in der Nähe des Ortes Wagram, etwa 15 Kilometer nordöstlich von Wien, auf den weitläufigen Ebenen östlich der Donau statt. Das flache Gelände erlaubte eine weite Entfaltung der Truppen und große Kavallerieangriffe. Napoleon wählte dieses Gebiet strategisch, da es ihm ermöglichte, die Donau erneut zu überqueren und die österreichischen Verteidigungslinien anzugreifen"}, {"kategorie": "", "text": "Die französische Armee zählte etwa 140.000 Mann, darunter Truppen aus verschiedenen verbündeten Staaten wie Italien, Sachsen und Bayern. Die österreichische Armee unter Erzherzog Karl bestand aus etwa 127.000 Soldaten. Obwohl zahlenmäßig unterlegen, waren die österreichischen Truppen gut positioniert und bereit, Napoleon erneut entgegenzutreten"}, {"kategorie": "", "text": "Am 5. Juli begann die Schlacht mit einer Reihe von Artillerieduellen, die zu schweren Verlusten auf beiden Seiten führten. Die Franzosen konnten zunächst leichte Fortschritte machen, aber die starke Verteidigung der Österreicher verhinderte einen Durchbruch"}, {"kategorie": "", "text": "Am 6. Juli starteten beide Seiten großangelegte Offensiven. Napoleon setzte massive Artillerie ein, um die österreichische Linie zu durchbrechen, und führte dann einen entscheidenden Angriff auf das Zentrum der österreichischen Armee.\nErzherzog Karl versuchte, Napoleons linke Flanke anzugreifen, konnte aber das französische Zentrum nicht durchbrechen. Die Franzosen gelangten schließlich durch die geschwächten österreichischen Linien, was die Österreicher zum Rückzug zwang"}, {"kategorie": "", "text": "Die Verluste waren enorm: Beide Seiten verloren zusammen mehr als 70.000 Soldaten. Diese Zahl machte die Schlacht bei Wagram zu einer der verlustreichsten der Napoleonischen Kriege.\nDer österreichische Rückzug führte zum [[Frieden]] von Schönbrunn im Oktober 1809, der Österreich zu schweren Gebietsabtretungen und politischen Zugeständnissen zwang."}]'::jsonb, ''),
  ('heilige-allianz', 'Heilige Allianz', '', '', '', '', 'Heilige Allianz', '[{"kategorie": "hist.", "text": "\"Bündnis, das am 26. September 1815 von den Monarchen Russlands (Zar Alexander I.), Österreichs (Kaiser [[Franz]] I.) und Preußens (König Friedrich Wilhelm III.) gegründet wurde\""}, {"kategorie": "", "text": "Ziel dieses Bündnisses war die Stabilisierung und Bewahrung der monarchischen und christlichen Ordnung in Europa nach den [[Napoleonischen]] Kriegen"}, {"kategorie": "", "text": "Die Heilige Allianz wollte die christlichen Werte und die „göttliche Ordnung“ in der Politik betonen und dabei eine monarchisch-absolutistische Herrschaft in Europa sichern. Sie propagierte das Ideal einer friedlichen Zusammenarbeit und gegenseitigen Unterstützung der Monarchen Europas, um revolutionären und liberalen Bewegungen entgegenzuwirken"}, {"kategorie": "", "text": "Die Gründungsmitglieder waren Russland, Österreich und Preußen. Bald schlossen sich fast alle europäischen Monarchien der Allianz an, außer Großbritannien, das Osmanische Reich und der Kirchenstaat (der Papst)"}, {"kategorie": "", "text": "Das Bündnis verstand sich als Vereinigung der christlichen Herrscher und war offen für alle Monarchien, die sich den Idealen von Frieden und Stabilität verpflichteten. Die Heilige Allianz war ein Symbol der konservativen [[Restauration]] und gegen die Ideen der Französischen Revolution gerichtet, wie Freiheit, Gleichheit und nationale Selbstbestimmung"}, {"kategorie": "", "text": "Die Heilige Allianz entstand im Kontext des [[Wiener]] Kongresses (1814–1815), der eine Neuordnung Europas nach den Napoleonischen Kriegen festlegte. Sie spielte eine Schlüsselrolle dabei, die im Wiener Kongress vereinbarte Machtbalance und Ordnung durchzusetzen"}, {"kategorie": "", "text": "Die Allianz verlor in den 1830er Jahren an Einfluss, als die revolutionären Bewegungen in Europa zunahmen und die liberale Öffentlichkeit zunehmend an Macht gewann. Der Einfluss der Heiligen Allianz schwand, und sie zerfiel nach den [[Revolutionen]] von 1848."}]'::jsonb, ''),
  ('habsbuagische-reichsinsigniin', 'Habsbuagische Reichsinsigniin', '', '', '', '', 'Habsburgische Reichsinsignien', '[{"kategorie": "hist.", "text": "\"Sammlung von symbolischen Gegenständen, die die kaiserliche Macht und Herrschaft der [[Habsburgerdynastie]] repräsentierten\""}, {"kategorie": "", "text": "Bestandteile der Habsburgischen Reichsinsignien: (i) die [[Kaiserkrone]] (die zentrale Krone der Insignien ist die [[Rudolfskrone]], die 1602 für Kaiser Rudolf II. angefertigt wurde. Sie war später, ab 1806, die Kaiserkrone des [[Kaisertums]] Österreich und symbolisierte die kaiserliche Würde und Macht der [[Habsburger]]),  (ii) Zepter und Reichsapfel (diese beiden Objekte sind weitere wesentliche Bestandteile der [[Insignien]]. Das [[Zepter]] steht für die weltliche Macht des [[Kaisers]], während der [[Reichsapfel]] - ein goldener, kugelförmiger Gegenstand - die Herrschaft über die Welt symbolisiert),  (iii) [[Reichsschwert]] (dieses Schwert wurde ebenfalls bei Krönungen und feierlichen Anlässen verwendet und diente als Symbol der Verteidigung des Reiches und der kaiserlichen Macht),  (iv) Krönungsmantel (der Krönungsmantel ist ein textiles Symbol für die königliche oder kaiserliche Würde),  (v) [[Heilige]] Lanze (ein weiteres Objekt, das oft zu den Reichsinsignien gezählt wird, ist die sogenannte Heilige Lanze, die als Symbol der kaiserlichen Macht und des Schutzes des Reiches diente)"}, {"kategorie": "", "text": "Die [[Habsburger]] behielten die Kontrolle über die [[Reichsinsignien]] während ihrer langen Herrschaft über das [[Heilige]] Römische Reich und später über das [[Kaisertum]] Österreich. Nach der Auflösung des Heiligen Römischen Reiches 1806 und der Gründung des Kaisertums Österreich blieben die Insignien ein wichtiges Symbol der habsburgischen Herrschaft"}, {"kategorie": "", "text": "Die Reichsinsignien symbolisierten die göttliche Berufung des Herrschers und seine Rolle als Beschützer des Reiches und des Christentums. wurden bei wichtigen Anlässen wie der Krönung des Kaisers verwendet, hatten eine starke symbolische Bedeutung und standen für die Vereinigung von geistlicher und weltlicher Macht"}, {"kategorie": "", "text": "Die Habsburgischen Reichsinsignien sind eine bedeutende Sammlung zeremonieller Objekte, die die kaiserliche Macht der Habsburgerdynastie verkörpern und heute allesamt in der [[Wiener]] Schatzkammer der [[Hofburg]] besichtigt werden können."}]'::jsonb, ''),
  ('reichsapfae', 'Reichsåpfä', '', '', '', '', 'Reichsapfel', '[{"kategorie": "hist.", "text": "\"historisches Herrschaftssymbol und ein bedeutendes [[Insigne]], das die weltliche Macht und das universale Herrschaftsrecht eines [[Monarchen]] verkörpert\""}, {"kategorie": "", "text": "Der Reichsapfel wurde häufig in der europäischen Krönungstradition verwendet und ist insbesondere als Teil der Insignien des [[Heiligen]] Römischen Reiches bedeutsam"}, {"kategorie": "", "text": "Der Reichsapfel stellt die Weltkugel dar und symbolisiert die Herrschaft des [[Kaisers]] oder [[Königs]] über die Welt. Er wird oft von einem Kreuz gekrönt, was den Anspruch verdeutlicht, dass die weltliche Macht des Herrschers unter christlichem Einfluss steht und von göttlicher Gnade gestützt wird"}, {"kategorie": "", "text": "Als Symbol für Einheit und universale Autorität ist der Reichsapfel häufig bei Kaiserkrönungen und anderen feierlichen Anlässen verwendet worden. Der wohl bekannteste Reichsapfel ist der Reichsapfel des [[Heiligen]] Römischen Reiches, der Teil der Krönungsinsignien des römisch-deutschen Kaisers war und heute in der [[Wiener]] Schatzkammer aufbewahrt wird"}, {"kategorie": "", "text": "Dieser Reichsapfel besteht aus Gold und ist mit einem Kreuz gekrönt. Er stammt aus dem 12. Jahrhundert und repräsentiert die Kontinuität und Autorität des Heiligen Römischen Reiches"}, {"kategorie": "", "text": "Der Reichsapfel erscheint oft in historischen Darstellungen von Herrschern sowie in der bildenden Kunst und Architektur als Zeichen der Macht und Legitimität. Er ist in Wappen, Skulpturen und Gemälden zu finden und repräsentiert dort die Verbindung zwischen weltlicher und geistlicher Herrschaft."}]'::jsonb, ''),
  ('heilige-launzn', 'Heilige Launzn', '', '', '', '', 'Heilige Lanze', '[{"kategorie": "hist.", "text": "\"bedeutendes Relikt und Herrschaftsinsigne des [[Heiligen]] Römischen Reiches (auch als \"Lanze des Heiligen Mauritius\" oder [[Reichslanze]] bekannt)\""}, {"kategorie": "", "text": "Sie ist in der [[Wiener]] Schatzkammer ausgestellt und galt als ein Symbol der göttlichen Legitimation und des Schutzes für den römisch-deutschen Kaiser. Die Lanze war Teil der [[Reichsinsignien]], die bei der Krönung und anderen wichtigen Zeremonien eingesetzt wurden"}, {"kategorie": "", "text": "Die Heilige Lanze gilt als eines der wichtigsten Herrschaftszeichen und war für die [[Kaiser]] des Heiligen Römischen Reiches von besonderer religiöser Bedeutung. Ihr wurde nachgesagt, sie sei eine der Lanzoiden der biblischen Geschichte: Die Lanze, mit der der römische Soldat Longinus die Seite Jesu durchbohrt habe. Sie symbolisierte die göttliche Macht und den Schutz des Kaisers und stand für die Verpflichtung des Herrschers, das Christentum und das Reich zu verteidigen"}, {"kategorie": "", "text": "Die Heilige Lanze besteht aus einem langen Eisenschaft, in den ein Nagel eingefügt ist, der angeblich als Reliquie der Kreuzigung Jesu verehrt wurde. Die Lanze wurde im Laufe der Jahrhunderte mehrmals verstärkt und mit einem goldenen Silberband versehen, auf dem der Name und die Titel mehrerer Kaiser eingraviert sind. Diese Bandagierungen und Inschriften zeugen von der Wertschätzung der Lanze als wichtiges Reliquiar und Symbol"}, {"kategorie": "", "text": "Die genaue Herkunft der Heiligen Lanze ist unklar, jedoch wurde sie spätestens seit der Zeit [[Ottos]] I. (10. Jahrhundert) als kaiserliche Insigne verwendet und in Krönungszeremonien als Zeichen der göttlichen Legitimation des Herrschers eingesetzt. Sie war über Jahrhunderte in der Obhut der römisch-deutschen Kaiser und spielte eine wichtige Rolle in Zeremonien und Feldzügen, da sie als Schutzzeichen und göttliche Macht für den Kaiser angesehen wurde"}, {"kategorie": "", "text": "Nach der Auflösung des [[Heiligen]] Römischen Reiches im Jahr 1806 verblieb die Heilige Lanze, zusammen mit anderen [[Reichsinsignien]], in Wien und ist seither Teil der Sammlung in der [[Wiener]] Schatzkammer."}]'::jsonb, ''),
  ('habsbuaga-kaisa', 'Habsbuaga Kaisa', '', '', '', '', 'Habsburger Kaiser', '[{"kategorie": "hist.", "text": "\"die Herrscher aus der Dynastie der [[Habsburger]], die über Jahrhunderte hinweg eine zentrale Rolle in der europäischen Geschichte spielten und das [[Heilige]] Römische Reich sowie später das [[Kaisertum]] Österreich und die [[Donaumonarchie]] Österreich-Ungarn regierten\""}, {"kategorie": "", "text": "[[Heiliges]] Römisches Reich (1438–1806): Die Habsburger stellten ab 1438 fast ununterbrochen die [[römisch-deutschen]] Kaiser. Dieser Titel verlieh ihnen die Herrschaft über das [[Heilige]] Römische Reich Deutscher Nation, eine lose Föderation aus Königreichen, Fürstentümern und freien Städten. Der Titel des Kaisers war formal durch eine Wahl der [[Kurfürsten]] legitimiert, wurde jedoch häufig innerhalb der habsburgischen Familie vererbt"}, {"kategorie": "", "text": "Gründung des Kaisertums Österreich (1804): Mit der Gründung des Kaisertums Österreich 1804 erklärte Kaiser Franz II. sich als Franz I. zum ersten Kaiser von Österreich, um das Prestige des kaiserlichen Titels zu sichern, nachdem das Heilige Römische Reich durch die [[napoleonischen]] Kriege bedroht war. 1806 legte Franz II. die Krone des Heiligen Römischen Reiches nieder, womit das Reich formell aufgelöst wurde. Von da an bis 1918 regierten die Habsburger als Kaiser von Österreich und später als Kaiser von Österreich-Ungarn (ab 1867), wobei das Reich nun auf die Habsburgischen [[Erblande]] und nicht mehr auf das gesamte Heilige Römische Reich beschränkt war"}, {"kategorie": "", "text": "Österreich-Ungarn und die Donaumonarchie: Nach dem [[Österreichisch-Ungarischen]] Ausgleich von 1867 entstand die Donaumonarchie Österreich-Ungarn. Diese [[Doppelmonarchie]] bestand aus dem [[Kaisertum]] Österreich und dem [[Königreich]] Ungarn, die jeweils über autonome Regierungssysteme verfügten, jedoch durch den Kaiser und König in Personalunion regiert wurden"}, {"kategorie": "", "text": "Die Habsburger herrschten über ein Vielvölkerreich, das ethnisch und kulturell vielfältig war. Kaiser [[Franz]] Joseph I. regierte als einer der letzten bedeutenden Habsburger Kaiser fast 68 Jahre und versuchte, die Einheit und Stabilität der Monarchie aufrechtzuerhalten"}, {"kategorie": "", "text": "Nach dem [[Ersten]] Weltkrieg und dem Zerfall von [[Österreich-Ungarn]] im Jahr 1918 endete die habsburgische Kaiserherrschaft. Kaiser [[Karl]] I. verzichtete zwar nicht formell auf den Thron, erklärte jedoch, keine Regierungsgeschäfte mehr führen zu wollen. Die [[Republik]] Österreich wurde gegründet, und die Habsburger mussten ins Exil gehen"}, {"kategorie": "", "text": "Die Habsburger Kaiser trugen zur europäischen Geschichte durch geschickte Heiratspolitik, kulturelle Förderung und die Errichtung eines komplexen Vielvölkerreiches bei. Sie strebten nach einem stabilen und machtvollen Reich, das den katholischen Glauben und die Ordnung in Europa bewahren sollte.\nIhre Regentschaft hinterließ einen bedeutenden Einfluss auf die Architektur, Kultur und Politik in Europa, insbesondere in den habsburgischen Kernländern wie Österreich, Böhmen, Ungarn und Spanien."}]'::jsonb, ''),
  ('heiliges-roemisches-reich-deitscha-nation', 'Heiliges Römisches Reich Deitscha Nation', '', '', '', '', 'Heiliges Römisches Reich Deutscher Nation', '[{"kategorie": "hist.", "text": "\"loses Reichsgebilde in Mitteleuropa, das vom 10. Jahrhundert bis zur Auflösung im Jahr 1806 bestand\""}, {"kategorie": "", "text": "Gegründet wurde es mit der Kaiserkrönung [[Ottos]] des Großen im Jahr 962 und bestand bis zu den [[Napoleonischen]] Kriegen"}, {"kategorie": "", "text": "Es war kein einheitlicher Nationalstaat, sondern ein komplexer Zusammenschluss aus [[Königreichen]], [[Fürstentümern]], [[Herzogtümern]], freien Städten und geistlichen Territorien, die unter einem gemeinsamen Kaiser standen"}, {"kategorie": "", "text": "Der Begriff „Heilig“ verweist auf die Verbindung des Reiches mit der katholischen Kirche und die sakrale Rolle des Kaisers als „Schutzherr“ des Christentums. „Römisch“ bezieht sich auf den Anspruch, das Erbe des Römischen Reiches fortzuführen und eine universelle Herrschaftsidee zu vertreten. „Deutscher Nation“ wurde im 15. Jahrhundert ergänzt, um den geografischen Schwerpunkt auf die deutschsprachigen Gebiete Europas zu betonen"}, {"kategorie": "", "text": "Das Reich war ein feudalistisch geprägtes Gebilde mit einer dezentralen Struktur. Es bestand aus vielen verschiedenen Herrschaftsgebieten, die weitgehend autonom regiert wurden. An der Spitze stand der [[römisch-deutsche]] Kaiser, der von den [[Kurfürsten]] gewählt wurde. Seine Macht war jedoch begrenzt, da die Territorien des Reiches große Selbstständigkeit besaßen"}, {"kategorie": "", "text": "Wichtige Reichsorgane waren der [[Reichstag]] und das [[Reichskammergericht]], die als zentrale Institutionen fungierten, um Konflikte beizulegen und die Ordnung aufrechtzuerhalten"}, {"kategorie": "", "text": "Die Kaiser des Reiches wurden von den [[Kurfürsten]] gewählt und oft in Rom gekrönt. Sie trugen den Titel des à„römisch-deutschen Kaisers“ und galten als Beschützer der katholischen Kirche und der Christenheit"}, {"kategorie": "", "text": "Die [[Habsburger]] stellten ab 1438 fast ununterbrochen die Kaiser, wodurch sich das Zentrum des Reiches zunehmend nach Österreich verlagerte. Neben den deutschsprachigen Regionen umfasste das Reich auch Teile Italiens, Burgunds und Böhmens und war damit ein Vielvölkerreich mit ethnischer und kultureller Vielfalt"}, {"kategorie": "", "text": "Das Reich zerbrach infolge der [[Napoleonischen]] Kriege. Kaiser [[Franz]] II. legte 1806 die Krone nieder und erklärte das Reich für aufgelöst, um das neu gegründete [[Kaisertum]] Österreich zu schützen."}]'::jsonb, ''),
  ('roemisch-deitsche-kaisa', 'Römisch-deitsche Kaisa', '', '', '', '', 'Römisch-Deutsche Kaiser', '[{"kategorie": "hist.", "text": "\"die Herrscher des [[Heiligen]] Römischen Reiches, die als höchste weltliche und geistliche Autorität in Mitteleuropa galten\""}, {"kategorie": "", "text": "Ihre Herrschaft begann formal mit der Krönung [[Ottos]] des Großen im Jahr 962 und endete mit der Auflösung des Reiches 1806 durch Kaiser [[Franz]] II"}, {"kategorie": "", "text": "Die römisch-deutschen Kaiser betrachteten sich als Nachfolger der römischen Kaiser und beanspruchten sowohl die weltliche als auch die sakrale Herrschaft über das Reich und seine vielen Territorien"}, {"kategorie": "", "text": "Der Titel „römisch-deutscher Kaiser“ verweist auf die Verbindung des mittelalterlichen [[Kaisertums]] mit der Tradition des antiken Römischen Reiches und der christlichen Herrschaftsidee. Die Kaiser galten als Schutzherren der katholischen Kirche und als Verteidiger des Glaubens. Sie sahen ihre Herrschaft als von Gott legitimiert und verstanden sich als weltliche Repräsentanten Gottes auf Erden"}, {"kategorie": "", "text": "Die römisch-deutschen Kaiser wurden von den [[Kurfürsten]] des Reiches gewählt, einem exklusiven Kreis von Fürsten, die das Recht hatten, den König des Reiches zu bestimmen. Dieser Wahlkönig wurde oft später zum [[Kaiser]] gekrönt"}, {"kategorie": "", "text": "Die Krönung zum Kaiser erfolgte traditionell in Rom durch den Papst, was die enge Verbindung von Kaiserwürde und Kirche symbolisierte. Ab dem 16. Jahrhundert ließ man jedoch oft von der Romreise ab und vollzog die Krönung innerhalb der Reichsgrenzen"}, {"kategorie": "", "text": "Die römisch-deutschen Kaiser hatten eine beschränkte Herrschaftsmacht, da das Reich ein loser Verband autonomer [[Fürstentümer]], [[Herzogtümer]], [[Bistümer]] und [[freier]] Städte war. Ihre Autorität war daher oft mehr symbolisch als praktisch, besonders in späteren Jahrhunderten"}, {"kategorie": "", "text": "Seit dem 15. Jahrhundert stellten fast ausschließlich die [[Habsburger]] die Kaiser, beginnend mit [[Friedrich]] III. (gewählt 1440, gekrönt 1452). Diese Kontinuität führte zur langen Dominanz der Habsburger im Reich und verfestigte die Kaiserwürde innerhalb der habsburgischen Dynastie. Die habsburgischen Kaiser verlagerten den Reichsschwerpunkt zunehmend nach Österreich und prägten die Geschichte des Heiligen Römischen Reiches bis zu dessen Ende"}, {"kategorie": "", "text": "Die römisch-deutsche Kaiserwürde endete 1806, als Kaiser [[Franz]] II. das Amt niederlegte und das [[Heilige]] Römische Reich auflöste. Dieser Schritt erfolgte in Folge der [[napoleonischen]] Kriege und der Gründung des [[Kaisertums]] Österreich durch [[Franz]] II. im Jahr 1804, wodurch die habsburgische Herrschaft fortgesetzt wurde."}]'::jsonb, ''),
  ('schlocht-bei-mohatsch', 'Schlocht bei Mohatsch', '', '', '', '', 'Schlacht bei Mohács', '[{"kategorie": "hist.", "text": "\"Schlacht, welche am 29. August 1526 zwischen den Truppen des [[Königreichs]] Ungarn und den osmanischen Streitkräften unter Sultan Süleyman dem Prächtigen stattfand\""}, {"kategorie": "", "text": "Sie gilt als eine der bedeutendsten Schlachten in der Geschichte Mitteleuropas und führte zu tiefgreifenden politischen Veränderungen, insbesondere für das ungarische und das habsburgische Herrschaftsgebiet"}, {"kategorie": "", "text": "Die Schlacht war Teil der Osmanischen Expansion nach Mitteleuropa. Sultan Süleyman der Prächtige wollte seinen Einfluss im Balkanraum und darüber hinaus ausdehnen, nachdem er bereits große Teile Südosteuropas erobert hatte. Ungarn unter König Ludwig II. stand dieser Expansion gegenüber, war jedoch militärisch unterlegen und schlecht vorbereitet"}, {"kategorie": "", "text": "Die Schlacht dauerte nur etwa zwei Stunden und endete in einer verheerenden Niederlage für die ungarischen Truppen. Die Osmanen nutzten ihre zahlenmäßige Überlegenheit und ihre erfahrene, gut ausgerüstete Armee, um die ungarischen Kräfte schnell zu überwältigen.\nKönig Ludwig II. fiel in der Schlacht, als er beim Rückzug in einem Sumpfgebiet ertrank. Sein Tod führte zum Machtvakuum und zur politischen Instabilität im Königreich Ungarn"}, {"kategorie": "", "text": "Die Niederlage in der Schlacht bei Mohács führte zum Zusammenbruch des ungarischen Königreichs und zur Teilung Ungarns. Ein Teil Ungarns fiel unter direkte osmanische Herrschaft, während der westliche Teil und die Hauptstadt Pressburg (heute Bratislava) unter habsburgischen Einfluss gerieten. Durch dynastische Ansprüche übernahm der Habsburger [[Ferdinand]] I. den ungarischen Königstitel und machte Ungarn zu einem zentralen Bestandteil der habsburgischen [[Monarchie]]. Dies verstärkte den Einfluss der [[Habsburger]] in Mitteleuropa und führte zur langfristigen Integration Ungarns in das habsburgische Herrschaftsgebiet"}, {"kategorie": "", "text": "Die Schlacht bei Mohács markierte den Beginn einer langen Auseinandersetzung zwischen dem [[Habsburgerreich]] und dem Osmanischen Reich um die Kontrolle über Ungarn und die Vorherrschaft in Mitteleuropa. Die Schlacht gilt als Symbol für das Ende des mittelalterlichen Königreichs Ungarn und den Beginn der habsburgisch-osmanischen Rivalität, die Mitteleuropa über Jahrhunderte hinweg prägte"}]'::jsonb, ''),
  ('oestarreichischa-eabfoigekriag', 'Östarreichischa Eabfoigekriag', '', '', '', '', 'Österreichischer Erbfolgekrieg', '[{"kategorie": "hist.", "text": "\"europäischer Konflikt (1740–1748), der nach dem Tod von Kaiser [[Karl]] VI. ausbrach und sich um die Frage der Nachfolge im Habsburgerreich drehte\""}, {"kategorie": "", "text": "Karl VI., der letzte männliche [[Habsburger]] Kaiser, starb 1740 ohne einen männlichen Erben. Um seine Tochter [[Maria]] Theresia als seine Nachfolgerin zu sichern, hatte er 1713 die [[Pragmatische]] Sanktion erlassen, die die Erbfolge auch in weiblicher Linie erlaubte"}, {"kategorie": "", "text": "Obwohl Karl VI. versucht hatte, die Pragmatische Sanktion von den europäischen Mächten anerkennen zu lassen, stellten mehrere Staaten – darunter Preußen, Bayern, Frankreich und Spanien – die Thronfolge Maria Theresias infrage und wollten sich Teile der habsburgischen Erblande aneignen"}, {"kategorie": "", "text": "Der Krieg begann, als der preußische König Friedrich II. (Friedrich der Große) kurz nach dem Tod Karls VI. in das habsburgische Schlesien einfiel, ein reiches und strategisch wichtiges Gebiet. Friedrich nutzte die Unsicherheit über die Nachfolge, um Schlesien für Preußen zu erobern. Bayern, Frankreich und Spanien schlossen sich ebenfalls an und erhoben eigene Ansprüche auf habsburgische Gebiete, was den Konflikt schnell eskalieren ließ"}, {"kategorie": "", "text": "Auf der einen Seite stand Österreich, unterstützt von Großbritannien, den Niederlanden und später auch Russland. Maria Theresia kämpfte entschlossen, um die [[Habsburger]] Monarchie und ihre [[Erblande]] zu verteidigen"}, {"kategorie": "", "text": "Der Krieg bestand aus mehreren Schlachten und wechselnden Allianzen und zog sich über ganz Europa. Maria Theresia sicherte ihre Position als Herrscherin, indem sie 1745 ihren Ehemann Franz Stephan von Lothringen als Kaiser [[Franz]] I. zum [[römisch-deutschen]] Kaiser wählen ließ, wodurch die habsburgische Vormachtstellung gestärkt wurde"}, {"kategorie": "", "text": "Der Krieg endete mit dem [[Frieden]] von Aachen (Aix-la-Chapelle) im Jahr 1748. Maria Theresia konnte ihre Herrschaft über die meisten habsburgischen [[Erblande]] behaupten, musste jedoch Schlesien offiziell an Preußen abtreten"}, {"kategorie": "", "text": "Der Friede von Aachen bestätigte Maria Theresia als rechtmäßige Herrscherin der [[Habsburgermonarchie]] und beendete den Konflikt, ohne die Spannungen zwischen den europäischen Mächten langfristig zu lösen."}]'::jsonb, ''),
  ('schbanischa-eabfoigekriag', 'Schbanischa Eabfoigekriag', '', '', '', '', 'Spanischer Erbfolgekrieg', '[{"kategorie": "hist.", "text": "europäischer Konflikt (1701–1714), der nach dem Tod des spanischen Königs [[Karl]] II. ausbrach und um die Nachfolge im spanischen [[Königreich]] geführt wurde"}, {"kategorie": "", "text": "Der spanische König Karl II. starb 1700 kinderlos und ohne direkten Erben. Karl, der letzte [[Habsburger]] auf dem spanischen Thron, hinterließ ein riesiges Imperium in Europa und Übersee. In seinem Testament hatte Karl II. den französischen Philipp von Anjou, einen Enkel des französischen Königs Ludwig XIV., zum Erben bestimmt. Diese Entscheidung hätte die mächtigen spanischen Gebiete unter die Kontrolle der Bourbonen gebracht und das Machtgleichgewicht in Europa zugunsten Frankreichs verschoben"}, {"kategorie": "", "text": "Die Aussicht auf eine französisch-spanische Union unter dem Haus Bourbon führte zu großer Besorgnis unter den europäischen Mächten, da sie eine Vorherrschaft Frankreichs in Europa befürchteten. Eine Koalition aus England, den Niederlanden, Österreich und Preußen stellte sich gegen Frankreich und Spanien, um das europäische Machtgleichgewicht zu bewahren und die Ansprüche des österreichischen Erzherzogs Karl von Habsburg (später Kaiser [[Karl]] VI.) auf den spanischen Thron zu unterstützen"}, {"kategorie": "", "text": "Der Krieg zog sich über mehr als ein Jahrzehnt hin und fand auf verschiedenen Schauplätzen in Europa, darunter Spanien, Italien und den Niederlanden, sowie in Übersee statt. Die alliierten Truppen, geführt von bedeutenden Militärführern wie dem Herzog von Marlborough (England) und [[Prinz]] Eugen von Savoyen (Österreich), erzielten mehrere wichtige Siege, wie bei Blenheim (1704), Ramillies (1706) und Oudenaarde (1708)"}, {"kategorie": "", "text": "Der Krieg endete schließlich mit dem [[Frieden]] von Utrecht (1713) und dem [[Frieden]] von Rastatt (1714). Die Friedensverträge legten fest, dass [[Philipp]] von Anjou (Philipp V.) König von Spanien bleiben durfte, jedoch unter der Bedingung, dass die spanische und die französische Krone niemals in Personalunion vereint werden dürften"}, {"kategorie": "", "text": "Die spanischen Besitztümer in Italien und die Spanischen Niederlande wurden an Österreich abgetreten. Großbritannien sicherte sich Gibraltar und Menorca, sowie Handelsrechte in der Neuen Welt."}]'::jsonb, ''),
  ('friide-von-aachen', 'Friide von Aachen', '', '', '', '', 'Friede von Aachen', '[{"kategorie": "hist.", "text": "\"Friedensvertrag (auch \"Frieden von Aix-la-Chapelle\"), der am 18. Oktober 1748 unterzeichnet wurde und den [[Österreichischen]] Erbfolgekrieg (1740–1748) beendete\""}, {"kategorie": "", "text": "Der Vertrag stabilisierte vorübergehend das europäische Machtgleichgewicht, indem er den Status quo vor dem Krieg weitgehend wiederherstellte"}, {"kategorie": "", "text": "Der Österreichische Erbfolgekrieg brach aus, nachdem der habsburgische Kaiser [[Karl]] VI. ohne männlichen Erben starb und seine Tochterà Maria Theresia die Nachfolge im [[Habsburgerreich]] antrat. Obwohl die [[Pragmatische]] Sanktion ihre Thronfolge sichern sollte, stellten mehrere europäische Mächte, darunter Preußen, Frankreich und Bayern, diese infrage"}, {"kategorie": "", "text": "Der Frieden von Aachen sollte die territoriale Integrität des [[Habsburgerreiches]] sichern und das Machtgleichgewicht in Europa stabilisieren, ohne dass eine Seite einen entscheidenden Vorteil erhielt"}, {"kategorie": "", "text": "Territoriale Regelungen: (i) Preußen konnte Schlesien behalten, das es im Krieg von Österreich erobert hatte, was Preußens Stellung in Mitteleuropa stark festigte. Maria Theresia behielt jedoch die Kontrolle über den Großteil ihrer [[Erblande]];  (ii) Die Kolonialmächte Frankreich und Großbritannien gaben sich gegenseitig eroberte Kolonien in Nordamerika und Indien zurück, um die Spannungen außerhalb Europas zu verringern;  (iii) Die Vertragspartner anerkannten offiziell die [[Pragmatische]] Sanktion, was Maria Theresias Thronanspruch und die Einheit des Habsburgerreiches rechtlich absicherte"}, {"kategorie": "", "text": "Der Friede von Aachen bestätigte Preußens Aufstieg zur Großmacht und machte die Rivalität zwischen Österreich und Preußen um die Vorherrschaft in Deutschland zu einem zentralen Thema der mitteleuropäischen Politik. Obwohl der Friede von Aachen den Krieg beendete, löste er die Spannungen zwischen den europäischen Mächten nicht dauerhaft. Die ungelösten Konflikte führten wenige Jahre später zum [[Siebenjährigen]] Krieg (1756–1763)."}]'::jsonb, ''),
  ('friiden-von-utrecht', 'Friiden von Utrecht', '', '', '', '', 'Frieden von Utrecht', '[{"kategorie": "hist.", "text": "\"Reihe von Verträgen, die den [[Spanischen]] Erbfolgekrieg beendeten\""}, {"kategorie": "", "text": "Diese Friedensverträge wurden zwischen den europäischen Großmächten – darunter Frankreich, Großbritannien, Spanien und die Niederlande – geschlossen und legte ein neues Machtgleichgewicht in Europa fest, um die Vormachtstellung einzelner Staaten zu verhindern"}, {"kategorie": "", "text": "Spanien trat seine Besitzungen in den Niederlanden sowie in Italien (Neapel, Mailand, Sardinien) an das [[Habsburgerreich]] (Österreich) ab, womit Österreich an Einfluss gewann"}, {"kategorie": "", "text": "Großbritannien erhielt Gibraltar und Menorca sowie Handelsrechte in spanischen Kolonien (z. B. das Asiento, das Handelsmonopol für afrikanische Sklaven nach Spanisch-Amerika)"}, {"kategorie": "", "text": "Frankreich überließ Großbritannien einige Kolonien in Nordamerika, wie Neufundland und Akadien, was die britische Kolonialmacht stärkte"}, {"kategorie": "", "text": "Philipp von Anjou, ein Enkel Ludwigs XIV., wurde als Philipp V. als König von Spanien anerkannt, jedoch unter der Bedingung, dass die französische und die spanische Krone nicht in Personalunion vereinigt werden dürfen. Dies verhinderte eine zu starke Dominanz der Bourbonen"}, {"kategorie": "", "text": "Der Frieden legte die Grundlagen für das europäische Gleichgewichtssystem, das künftige Hegemonialansprüche eindämmen sollte. Er festigte die Stellung Großbritanniens als aufstrebende Kolonialmacht und stärkte Österreichs Position in Europa."}]'::jsonb, ''),
  ('friiden-von-rastatt', 'Friiden von Rastatt', '', '', '', '', 'Frieden von Rastatt', '[{"kategorie": "hist.", "text": "\"Friedensvertrag vom 7. März 1714, der zwischen Frankreich und Österreich geschlossen wurde und den [[Spanischen]] Erbfolgekrieg für das [[Heilige]] Römische Reich beendete\""}, {"kategorie": "", "text": "Zusammen mit dem [[Frieden]] von Utrecht (1713), der den Konflikt zwischen anderen europäischen Mächten geregelt hatte, markierte der Rastatter Frieden das Ende des Krieges und legte das neue Machtgleichgewicht in Europa fest"}, {"kategorie": "", "text": "Österreich erhielt die Spanischen Niederlande sowie die spanischen Besitzungen in Italien (Neapel, Mailand und Sardinien), was die habsburgische Macht in Südeuropa festigte. Frankreich gab Gebietsansprüche in diesen Regionen auf, behielt jedoch die von ihm kontrollierten französischen Gebiete"}, {"kategorie": "", "text": "Der Vertrag stärkte das [[Habsburgerreich]] und sicherte Österreichs Position als Großmacht in Europa. Frankreichs Einfluss wurde eingeschränkt, womit der Frieden das europäische Gleichgewicht wiederherstellte und künftige Konflikte eindämmen sollte"}, {"kategorie": "", "text": "Der Frieden von Rastatt trug zum Aufstieg Österreichs als europäische Macht bei und beendete Frankreichs Ausdehnungsversuche in die habsburgischen [[Erblande]]."}]'::jsonb, ''),
  ('friiden-von-hubertusburg', 'Friiden von Hubertusburg', '', '', '', '', 'Frieden von Hubertusburg', '[{"kategorie": "hist.", "text": "\"Friedensvertrag vom 15. Februar 1763, welcher den [[Siebenjährigen]] Krieg in Europa zwischen Preußen, Österreich und Sachsen beendete\""}, {"kategorie": "", "text": "Zusammen mit dem Frieden von Paris, der am selben Tag unterzeichnet wurde und den Krieg zwischen Großbritannien, Frankreich und Spanien regelte, markierte der Frieden von Hubertusburg das Ende eines globalen Konflikts und stabilisierte die politischen Verhältnisse in Mitteleuropa"}, {"kategorie": "", "text": "Der Vertrag stellte den Status quo vor dem Krieg wieder her: Preußen behielt Schlesien, was seinen Aufstieg zur europäischen Großmacht bestätigte, während Österreich und Sachsen keinerlei Gebietsgewinne oder Reparationen erhielten"}, {"kategorie": "", "text": "Preußens Großmachtstatus wurde gefestigt, und Friedrich der Große erlangte großes Ansehen"}, {"kategorie": "", "text": "Der Frieden brachte Mitteleuropa eine Phase der Ruhe, beendete aber die Rivalität zwischen Österreich und Preußen nicht, die die deutsche und österreichische Geschichte nachhaltig prägte."}]'::jsonb, ''),
  ('siibnjaeaeriga-kriag', 'Siibnjääriga Kriag', '', '', '', '', 'Siebenjähriger Krieg', '[{"kategorie": "hist.", "text": "\"globaler Konflikt (1756–1763), der als allererster „Weltkrieg“ gilt, da er Kämpfe auf mehreren Kontinenten – Europa, Nordamerika, Indien und auf den Weltmeeren – umfasste\""}, {"kategorie": "", "text": "Der Krieg entstand aus mehreren Machtkonflikten: Preußen und Österreich kämpften um die Vorherrschaft in Deutschland und insbesondere um das reiche Gebiet Schlesien, das Preußen im [[Österreichischen]] Erbfolgekrieg erobert hatte.\nEin weiterer Konflikt bestand zwischen Großbritannien und Frankreich, die um koloniale Vorherrschaft in Nordamerika (bekannt als Franzosen- und Indianerkrieg) und Indien wetteiferten"}, {"kategorie": "", "text": "Auf der einen Seite standen Preußen und Großbritannien (inklusive seiner deutschen Verbündeten wie Braunschweig und Hannover), auf der anderen Seite bildeten Österreich, Frankreich, Russland, Schweden und später Spanien eine Allianz. Diese Koalition wollte die Vorherrschaft Preußens und Großbritanniens schwächen und die verlorenen Gebiete zurückgewinnen"}, {"kategorie": "", "text": "In Europa erlangte Friedrich II. von Preußen den Ruf eines brillanten Militärstrategen, da er sich trotz der Übermacht der Koalition erfolgreich gegen mehrere Feinde verteidigte. Bedeutende Schlachten waren die Schlacht bei Roßbach (1757) und die Schlacht bei Leuthen (1757), in denen Preußen wichtige Siege errang. In Nordamerika gewann Großbritannien wichtige Schlachten gegen Frankreich und eroberte französische Gebiete wie Quebec und Montreal, was schließlich zur britischen Dominanz in Nordamerika führte. In Indien kämpften britische und französische Kolonialarmeen um die Vorherrschaft, wobei Großbritannien letztlich die Oberhand gewann und den Grundstein für das britische Kolonialreich in Indien legte"}, {"kategorie": "", "text": "Der Krieg endete 1763 mit dem Frieden von Paris und dem [[Frieden]] von Hubertusburg. Im Frieden von Paris musste Frankreich seine nordamerikanischen Kolonien (Kanada und das Land östlich des Mississippi) an Großbritannien abtreten, was die britische Vorherrschaft in Nordamerika sicherte. Auch in Indien gewann Großbritannien die Vormachtstellung. Der [[Frieden]] von Hubertusburg bestätigte Preußens Besitz von Schlesien und markierte den Aufstieg Preußens als Großmacht, festigte jedoch auch das österreichische Habsburgerreich."}]'::jsonb, ''),
  ('habsbuaga-gesetze', 'Habsbuaga-Gesetze', '', '', '', '', 'Habsburgergesetze', '[{"kategorie": "hist.", "text": "\"eine Reihe von gesetzlichen Bestimmungen, die in Österreich nach dem [[Ersten]] Weltkrieg und dem Ende der [[Monarchie]] erlassen wurden\""}, {"kategorie": "", "text": "Diese Gesetze betrafen die ehemalige kaiserliche Familie der [[Habsburger]] und regelten deren rechtlichen Status, Eigentumsansprüche und Aufenthalt in Österreich"}, {"kategorie": "", "text": "Nach der Gründung der [[Republik]] Österreich 1918/1919 erklärten die Habsburgergesetze die Abschaffung der Monarchie und entzogen der Familie Habsburg-Lothringen alle monarchischen Rechte. Die Gesetze sahen ein Exil für alle Mitglieder der Habsburgerfamilie vor, die nicht bereit waren, auf ihre Thronansprüche zu verzichten. Dies betraf insbesondere den letzten Kaiser [[Karl]] I. und seine Nachkommen"}, {"kategorie": "", "text": "Die Gesetze führten zur Enteignung des Vermögens der Habsburgerfamilie in Österreich, darunter Paläste, Ländereien und andere Besitztümer. Diese Eigentümer wurden als Staatseigentum betrachtet und verstaatlicht"}, {"kategorie": "", "text": "Ein Teil der historischen Kunst- und Kulturgüter ging an öffentliche Museen und Sammlungen, wie die Wiener [[Hofburg]] und die [[Schatzkammer]], die heute das kulturelle Erbe der Habsburger ausstellen"}, {"kategorie": "", "text": "Einige Mitglieder der Familie, wie Otto von Habsburg, unterzeichneten diese Erklärung, um die Rückkehr nach Österreich zu ermöglichen. Erst 1966 wurde Otto von Habsburg die Rückkehr ohne Einschränkungen gestattet"}, {"kategorie": "", "text": "Teile der Habsburgergesetze wurden später gelockert, aber die Enteignungen und der Verzicht auf monarchische Ansprüche sind weiterhin gültig. Die Republik Österreich erkennt die Habsburger als private Bürger ohne besondere Rechte an"}, {"kategorie": "", "text": "Die Habsburgergesetze sind in Österreich bis heute ein Symbol für die Trennung von Monarchie und Republik und die rechtliche Gleichstellung der ehemaligen kaiserlichen Familie."}]'::jsonb, ''),
  ('eazheazog-von-oestarreich', 'Eazheazog von Östarreich', '', '', '', '', 'Erzherzog von Österreich', '[{"kategorie": "hist.", "text": "\"Titel, der vom [[Haus]] Habsburg getragen wurde und ab dem späten Mittelalter ein Zeichen der herausragenden Stellung der habsburgischen Herrscher innerhalb des [[Heiligen]] Römischen Reiches und später in Europa war\""}, {"kategorie": "", "text": "Der Titel wurde mit dem [[Privilegium]] Maius begründet, einer gefälschten Urkunde, die Herzog [[Rudolf]] IV. von Habsburg im 14. Jahrhundert in Auftrag gab, um den Status der Habsburger zu erhöhen"}, {"kategorie": "", "text": "Der Titel à„Erzherzog“ stellte die österreichischen Herrscher formal auf eine Ebene mit den sieben [[Kurfürsten]] des Reiches und verlieh ihnen besondere Privilegien"}, {"kategorie": "", "text": "„Erzherzog von Österreich“ wurde ab diesem Zeitpunkt der offizielle Titel für die Herrscher Österreichs und symbolisierte ihre Vorherrschaft im Alpenraum und später darüber hinaus. Später wurde der Erzherzogstitel innerhalb der Habsburger-Familie auf die männlichen Mitglieder ausgeweitet, um deren hohe dynastische Stellung zu betonen"}, {"kategorie": "", "text": "Der Titel behielt seine Bedeutung bis zum Ende der [[Monarchie]] 1918 und ist heute ein historischer Ehrentitel, der eng mit der Geschichte der [[Habsburger-Dynastie]] und Österreichs verbunden bleibt."}]'::jsonb, ''),
  ('kaisakrone-des-heiligen-roemischen-reiches', 'Kaisakrone des Heiligen Römischen Reiches', '', '', '', '', 'Kaiserkrone des Heiligen Römischen Reiches', '[{"kategorie": "hist.", "text": "\"Krone, die vom 11. Jahrhundert bis zum Ende des [[Heiligen]] Römischen Reiches 1806 als Krönungsinsigne für die römisch-deutschen Kaiser verwendet wurd\""}, {"kategorie": "", "text": "Diese Krone, oft auch [[Reichskrone]] genannt, symbolisierte die höchste Macht und Herrschaftsautorität der Kaiser über das Heilige Römische Reich"}, {"kategorie": "", "text": "Die Kaiserkrone ist einzigartig in ihrer Gestaltung und unterscheidet sich von anderen europäischen Kronen. Sie besteht aus acht goldenen Platten, die mit Edelsteinen und Emailarbeiten verziert sind und eine oktogonale Form bilden. Auf der Vorderseite der Krone befindet sich ein großer Kreuzaufsatz, der die Verbindung zwischen [[Kaiser]] und Kirche sowie die göttliche Legitimation des [[Kaisertums]] symbolisiert. Die Verzierungen zeigen biblische Szenen und Symbole, die die Rolle des Kaisers als Verteidiger des Glaubens unterstreichen"}, {"kategorie": "", "text": "Diese Krone wurde in der Reichskrone-Sammlung der Reichsinsignien aufbewahrt, die heute größtenteils in der [[Schatzkammer]] der [[Wiener]] Hofburg ausgestellt sind"}, {"kategorie": "", "text": "Die Kaiserkrone ist ein bedeutendes Kunstwerk und Symbol für die lange Geschichte und das kulturelle Erbe des Heiligen Römischen Reiches."}]'::jsonb, ''),
  ('privilegium-maius', 'Privilegium Maius', '', '', '', '', 'Privilegium Maius', '[{"kategorie": "hist.", "text": "\"gefälschte Urkundensammlung, die Herzog [[Rudolf]] IV. von Habsburg um 1358/59 in Auftrag gab, um die Macht und den Einfluss seines Hauses in Österreich zu stärken\""}, {"kategorie": "", "text": "Diese Urkunden sollten die Herrschaftsrechte der [[Habsburger]] aufwerten und beinhalteten unter anderem Ansprüche auf den Titel des [[Erzherzogs]], der mit besonderen Rechten und Privilegien verbunden war"}, {"kategorie": "", "text": "Das Privilegium Maius baute auf dem echten, jedoch weniger umfangreichen [[Privilegium]] Minus von 1156 auf, das Kaiser [[Friedrich]] I. Barbarossa den Babenbergern gewährt hatte. Die neuen Dokumente sollten Österreich den Rang eines [[Erzherzogtums]] verleihen und die habsburgischen Herrschaftsrechte denen der [[Kurfürsten]] angleichen"}, {"kategorie": "", "text": "Zwar wurde das Privilegium Maius zunächst als Fälschung entlarvt, doch später, unter Kaiser [[Friedrich]] III., wurde es offiziell anerkannt und die Erzherzogswürde schließlich Teil des habsburgischen Titels"}, {"kategorie": "", "text": "Damit markiert das Privilegium Maius einen wichtigen Schritt zur Festigung der habsburgischen Dynastie und ihrer führenden Rolle im [[Heiligen]] Römischen Reich."}]'::jsonb, ''),
  ('wacknrooda-bruckn', 'Wacknrooda Bruckn', '', '', '', '', 'Wackenroder Brücke', '[{"kategorie": "allg.", "text": "(Morizgasse/St. Johann-Gasse)"}]'::jsonb, ''),
  ('sankt-veit-bruckn', 'Sankt-Veit-Bruckn', '', '', '', '', 'Sankt-Veit-Brücke', '[{"kategorie": "allg.", "text": "(Hietzinger Kai/Hochsatzengasse)"}]'::jsonb, ''),
  ('schoenbrunna-schlossbruckn', 'Schönbrunna Schlossbruckn', '', '', '', '', 'Schönbrunner Schlossbrücke', '[{"kategorie": "allg.", "text": "(Schönbrunner Schlossstraße)"}]'::jsonb, ''),
  ('hittlduafa-bruckn', 'Hittlduafa Bruckn', '', '', '', '', 'Hütteldorfer Brücke', '[{"kategorie": "allg.", "text": "(Brudermanngasse/Rußpekgasse)"}]'::jsonb, ''),
  ('zoiaumts-schdeeg', 'Zoiaumts-Schdeeg', '', '', '', '', 'Zollamtssteg', '[{"kategorie": "allg.", "text": "(Stubenring/Hauptzollamt)"}]'::jsonb, ''),
  ('reinprechtsduafa-bruckn', 'Reinprechtsduafa Bruckn', '', '', '', '', 'Reinprechtsdorfer Brücke', '[{"kategorie": "allg.", "text": "(Reinprechtsdorfer Straße/Anilingasse)"}]'::jsonb, ''),
  ('nussduafa-wea-und-schleisnaunloog', 'Nussduafa Wea- und Schleisnaunloog', '', '', '', '', 'Nussdorfer Wehr- und Schleusenanlage', '[{"kategorie": "allg.", "text": "\"Schleuse Nussdorf\" bzw. \"Nussdorfer Schleuse\" = \"historische und technisch bedeutende Hochwasserschutz- und Schifffahrtsanlage am Eingang des [[Donaukanals]] im Wiener Stadtteil [[Nussdorf]], der im 19. Wiener Gemeindebezirk ([[Döbling]]) liegt"}, {"kategorie": "", "text": "Sie wurde im späten 19. Jahrhundert errichtet, um den Wasserstand im Donaukanal zu regulieren, Hochwasserschutz zu bieten und die Schifffahrt zu ermöglichen. Das Wehr und die Schleusenanlage sind ein prägendes Beispiel für die fortschrittliche Ingenieurskunst der Zeit und zugleich ein architektonisches Werk des berühmten Wiener Architekten Otto Wagner"}, {"kategorie": "", "text": "Die Anlage wurde von Otto Wagner, einem der bedeutendsten Architekten des Wiener Jugendstils, entworfen. Wagner war zu dieser Zeit als Stadtplaner tätig und gestaltete die technische Anlage mit großer architektonischer Sorgfalt, was dem Bauwerk eine ästhetische und kunsthistorische Bedeutung verleiht"}, {"kategorie": "", "text": "Die Wehranlage wird von zwei markanten Jugendstil-Pavillons flankiert, die als Maschinenhäuser dienen und Wagners typischen Stil mit klaren, funktionalen Formen und dekorativen Elementen zeigen"}, {"kategorie": "", "text": "Das Wehr selbst besteht aus einer Reihe von verschließbaren Toren, die das Wasser aus der Donau zurückhalten. Die Schleusenanlage ermöglicht es Schiffen, den Höhenunterschied zwischen der [[Donau]] und dem [[Donaukanal]] zu überwinden"}, {"kategorie": "", "text": "Die Nussdorfer Wehr- und Schleusenanlage ist nicht nur eine bedeutende technische Errungenschaft des späten 19. Jahrhunderts, sondern auch ein wichtiges Baudenkmal des Wiener Jugendstils. Die Anlage wird bis heute genutzt und ist ein wichtiger Bestandteil des Wiener Hochwasserschutzsystems."}]'::jsonb, ''),
  ('brigittenaua-schboan', 'Brigittenaua Schboan', '', '', '', '', 'Brigittenauer Sporn', '[{"kategorie": "allg.", "text": "\"markantes Teilungsbauwerk, das die Trennung zwischen der [[Donau]] und dem [[Donaukanal]] markiert\""}, {"kategorie": "", "text": "Er befindet sich im 20. Wiener Gemeindebezirk ([[Brigittenau]]) und wurde am 23. Januar 1973 durch den Gemeinderatsausschuss für Kultur offiziell benannt"}, {"kategorie": "", "text": "Der Sporn ist baulich einerseits durch die [[Schemerlbrücke]] mit [[Nussdorf]] im 19. Bezirk ([[Döbling]]) verbunden, die über das [[Nussdorfer]] Wehr führt, und andererseits durch die [[Nussdorfer]] Schleusenbrücke mit dem nördlichsten Abschnitt des [[Handelskai]]"}, {"kategorie": "", "text": "Die geographische und wasserbauliche Bedeutung des Brigittenauer Sporns liegt in seiner Funktion als Teilungs- und Regulierungsbauwerk, das den Wasserfluss zwischen der Donau und dem Donaukanal steuert."}]'::jsonb, ''),
  ('nussduafa-schboan', 'Nussduafa Schboan', '', '', '', '', 'Nussdorfer Sporn', '[{"kategorie": "", "text": "Er befindet sich im 20. Wiener Gemeindebezirk ([[Brigittenau]]) und wurde am 23. Januar 1973 durch den Gemeinderatsausschuss für Kultur offiziell benannt"}, {"kategorie": "", "text": "Der Sporn ist baulich einerseits durch die [[Schemerlbrücke]] mit [[Nussdorf]] im 19. Bezirk ([[Döbling]]) verbunden, die über das [[Nussdorfer]] Wehr führt, und andererseits durch die [[Nussdorfer]] Schleusenbrücke mit dem nördlichsten Abschnitt des [[Handelskai]]"}, {"kategorie": "", "text": "Die geographische und wasserbauliche Bedeutung des Brigittenauer Sporns liegt in seiner Funktion als Teilungs- und Regulierungsbauwerk, das den Wasserfluss zwischen der Donau und dem Donaukanal steuert."}]'::jsonb, ''),
  ('wiina-hoofn', 'Wiina Hoofn', '', '', '', '', 'Wiener Hafen', '[{"kategorie": "", "text": "Historisch reicht seine Bedeutung bis in die Römerzeit zurück, als es eine Schiffsanlegestelle nahe der heutigen [[Ruprechtskirche]] gab, die auch im Mittelalter intensiv genutzt wurde, insbesondere für Salztransporte"}, {"kategorie": "", "text": "Mit der [[Donauregulierung]] zwischen 1870 und 1875 begann die moderne Entwicklung des Wiener Hafens"}, {"kategorie": "", "text": "Das Kernstück des Wiener Hafens ist der [[Hafen]] Freudenau im 2. Bezirk ([[Leopoldstadt]]), der über 1,4 Millionen m² umfasst und als das größte trimodale Verkehrszentrum des Landes fungiert (Schiff, Bahn, Straße). Hier werden jährlich rund 1700 Frachtschiffe abgefertigt, und etwa 12 Millionen Tonnen Güter werden umgeschlagen"}, {"kategorie": "", "text": "Zusätzlich gibt es den [[Hafen]] Albern im 11. Bezirk ([[Simmering]]), der sich auf den Getreideumschlag spezialisiert hat, und den [[Ölhafen]] Lobau im 22. Bezirk ([[Donaustadt]]), der als wichtiger Umschlagsplatz für Erdölprodukte dient und auch als [[Winterhafen]] für Tankschiffe fungiert"}, {"kategorie": "", "text": "Diese als \"Wiener Hafen\" bezeichneten Hafenanlagen sind entscheidend für den internationalen Handel und die Versorgung der Region mit Waren und Gütern aller Art."}]'::jsonb, ''),
  ('freidenaua-hoofnbruckn', 'Freidenaua Hoofnbruckn', '', '', '', '', 'Freudenauer Hafenbrücke', '[{"kategorie": "allg.", "text": "\"Straßenbrücke im Bereich des [[Freudenauer]] Hafens, die zwischen 1956 und 1958 errichtet wurde, um das Hafengebiet im 2. Bezirk ([[Leopoldstadt]]) mit dem 11. Bezirk ([[Simmering]]) zu verbinden\""}, {"kategorie": "", "text": "Die Brücke überspannt den [[Donaukanal]] und die Zufahrt zum [[Freudenauer]] Hafen, auch als [[Winterhafen]] bezeichnet, und hat eine Länge von 352 Metern bei einer Breite von 15 Metern"}, {"kategorie": "", "text": "Die Brücke wurde nach dem Dywidag-System in Spannbetonbauweise errichtet, wobei erstmals in Österreich der freie Vorbau angewandt wurde, was es ermöglichte, die 89 Meter lange zentrale Spannweite ohne Gerüst zu errichten"}, {"kategorie": "", "text": "Die Brücke verbindet dieà Seitenhafenstraße im 2. Bezirk mit der [[Zinnergasse]] in [[Kaiserebersdorf]] und der [[Simmeringer]] Lände im 11. Bezirk"}, {"kategorie": "", "text": "Sie wurde nach der Zerstörung ihrer Vorgängerin, der sogenannten Brigittabrücke, am Ende des [[Zweiten]] Weltkriegs erbaut"}, {"kategorie": "", "text": "Heute dient die Freudenauer Hafenbrücke dem Individualverkehr und entlastet den Verkehr zwischen dem [[Handelskai]] und den südöstlichen Bezirken Wiens."}]'::jsonb, ''),
  ('freidenaua-hoofnschdrossn', 'Freidenaua Hoofnschdrossn', '', '', '', '', 'Freudenauer Hafenstraße', '[{"kategorie": "allg.", "text": "Straße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), welche im Jahr 1894 nach dem [[Freudenauer]] Winterhafen benannt wurde (erbaut in den Jahren 1889 bis 1902)"}, {"kategorie": "", "text": "Der Freudenauer Winterhafen ist ein bedeutender Teil des [[Wiener]] Hafensystems und dient als Schutzhafen bei Hochwasser und Eis. Ursprünglich wurde er als Umschlagplatz für Güter und zur Einlagerung von Schiffen während der Wintermonate genutzt"}, {"kategorie": "", "text": "Die Straße führt entlang dieses Hafens und verbindet die verschiedenen Hafenanlagen mit der städtischen Infrastruktur. Sie stellt eine wichtige Verbindung für den Güterverkehr dar, der über den Hafen Freudenau abgewickelt wird, der heute ein Teil des größten multimodalen Güterverkehrszentrums in Österreich ist"}, {"kategorie": "", "text": "Zudem dient die Freudenauer Hafenstraße als Zufahrtsstraße zu verschiedenen Lagerhäusern, Umschlagplätzen und weiteren logistischen Einrichtungen im Hafenbereich. Die Straße ist auch ein wichtiges Bindeglied zwischen der [[Leopoldstadt]] und den umliegenden Industriegebieten, insbesondere in Richtung des 11. Bezirks ([[Simmering]]), den sie über die nahe gelegene [[Freudenauer]] Hafenbrücke verbindet"}, {"kategorie": "", "text": "In unmittelbarer Nähe zur Freudenauer Hafenstraße befinden sich zudem Einrichtungen wie die [[Hauptkläranlage]] Wien und das [[Kraftwerk]] Freudenau, die in die industrielle und logistische Nutzung dieses Gebiets eingebettet sind."}]'::jsonb, '')
